window.BC=window.BC||{};window.BC.meta={"CAISO": {"groupLabel": {"CC_CHP": "CC CHP", "CC_REGULAR": "CC Regular", "COAL": "Coal", "COAL_BIT": "Coal Bituminous", "COAL_PRB": "Coal PRB", "CT_CHP": "CT CHP", "CT_PEAKER": "CT Peaker", "OTHER_FOSSIL": "Other Fossil", "ST_CHP": "Steam CHP", "ST_GAS": "Steam Gas"}, "groups": ["COAL", "COAL_PRB", "COAL_BIT", "CC_REGULAR", "CC_CHP", "CT_PEAKER", "CT_CHP", "ST_GAS", "ST_CHP", "OTHER_FOSSIL"], "years": [2023, 2024, 2025], "zones": ["NP15", "SP15", "ZP26"]}, "ERCOT": {"groupLabel": {"CC_CHP": "CC CHP", "CC_REGULAR": "CC Regular", "COAL_LIGNITE": "Coal Lignite", "COAL_PRB": "Coal PRB", "CT_CHP": "CT CHP", "CT_PEAKER": "CT Peaker", "OTHER_FOSSIL": "Other Fossil", "ST_CHP": "Steam CHP", "ST_GAS": "Steam Gas"}, "groups": ["COAL_LIGNITE", "COAL_PRB", "CC_REGULAR", "CC_CHP", "CT_PEAKER", "CT_CHP", "ST_GAS", "ST_CHP", "OTHER_FOSSIL"], "years": [2023, 2024, 2025], "zones": ["Houston", "North", "Northeast", "South", "South_Central", "West"]}, "MISO": {"groupLabel": {"CC_CHP": "CC CHP", "CC_REGULAR": "CC Regular", "COAL_BIT": "Coal Bituminous", "COAL_LIGNITE": "Coal Lignite", "COAL_PRB": "Coal PRB", "CT_CHP": "CT CHP", "CT_PEAKER": "CT Peaker", "OTHER_FOSSIL": "Other Fossil", "ST_CHP": "Steam CHP", "ST_GAS": "Steam Gas"}, "groups": ["COAL_LIGNITE", "COAL_PRB", "COAL_BIT", "CC_REGULAR", "CC_CHP", "CT_PEAKER", "CT_CHP", "ST_GAS", "ST_CHP", "OTHER_FOSSIL"], "years": [2023, 2024, 2025], "zones": ["MISO-East", "MISO-Illinois", "MISO-Indiana", "MISO-Plains", "MISO-South", "MISO-West"]}, "NEISO": {"groupLabel": {"CC_CHP": "CC CHP", "CC_REGULAR": "CC Regular", "COAL_BIT": "Coal Bituminous", "CT_CHP": "CT CHP", "CT_PEAKER": "CT Peaker", "OTHER_FOSSIL": "Other Fossil", "ST_CHP": "Steam CHP", "ST_GAS": "Steam Gas"}, "groups": ["COAL_BIT", "CC_REGULAR", "CC_CHP", "CT_PEAKER", "CT_CHP", "ST_GAS", "ST_CHP", "OTHER_FOSSIL"], "years": [2023, 2024, 2025], "zones": ["Boston", "Central", "Connecticut", "North"]}, "NYISO": {"groupLabel": {"CC_CHP": "CC CHP", "CC_REGULAR": "CC Regular", "COAL_BIT": "Coal Bituminous", "COAL_PRB": "Coal PRB", "CT_CHP": "CT CHP", "CT_PEAKER": "CT Peaker", "ST_CHP": "Steam CHP", "ST_GAS": "Steam Gas"}, "groups": ["COAL_PRB", "COAL_BIT", "CC_REGULAR", "CC_CHP", "CT_PEAKER", "CT_CHP", "ST_GAS", "ST_CHP"], "years": [2023, 2024, 2025], "zones": ["Capital_Hudson", "Long_Island", "Lower_Hudson", "NYC", "Upstate_West"]}, "PJM": {"groupLabel": {"CC_CHP": "CC CHP", "CC_REGULAR": "CC Regular", "COAL_BIT": "Coal Bituminous", "COAL_PRB": "Coal PRB", "COAL_WC": "Coal Waste", "CT_CHP": "CT CHP", "CT_PEAKER": "CT Peaker", "OTHER_FOSSIL": "Other Fossil", "ST_CHP": "Steam CHP", "ST_GAS": "Steam Gas"}, "groups": ["COAL_PRB", "COAL_BIT", "COAL_WC", "CC_REGULAR", "CC_CHP", "CT_PEAKER", "CT_CHP", "ST_GAS", "ST_CHP", "OTHER_FOSSIL"], "years": [2023, 2024, 2025], "zones": ["PJM_AEP_Ohio", "PJM_ATSI", "PJM_Central_PA", "PJM_ComEd", "PJM_Dominion", "PJM_EMAAC", "PJM_SWMAAC", "PJM_West_APS"]}};window.BC.manifest=[{"date": "2026-07-02", "definition": "MISO 37 (PROBE): market-wide RBDC energy+reserve co-opt genuinely IN the backcast LP for the first time (new run_year MISO branch -> unchanged _miso_design; requirement MSSC+400 MW = 4,353 MW, 8 ORDC steps $437-$3,500). Honest finding at 6-zone granularity: reserve clearing price EXACTLY $0 in all 26,280 hours \u2014 the ~4.4 GW market-wide requirement never binds against tens of GW of idle eligible headroom, and congestion does not change the market-wide sum (same result as the 3-zone miso3 probe and the PJM ORDC campaign). Dispatch differs from miso-36 only by degenerate-tie reshuffling (max LMP delta $0.29). Gates 1-3 unchanged from miso-35. Requirement NOT inflated, penalty NOT raised (rules #1/#11); structure retained. Tail lever moves to the zonal families (miso-38).", "file": "frontend/data/backcast/runs/2026-07-02-miso-37-coopt-wired.js", "id": "2026-07-02-miso-37-coopt-wired", "iso": "MISO", "label": "miso 37 coopt wired", "shorthand": "miso-37-coopt-wired", "years": [2023, 2024, 2025]}, {"date": "2026-07-02", "definition": "MISO 38 (KEEPER): miso-37 + LOCATIONAL reserve family per scope \u00a76 (--miso-zonal-reserves): MISO-South zonal operating-reserve family, requirement = within-zone MSSC 3,953 MW (BPM-002 \u00a73.3.2 zonal minimum, the 'pre-determined largest zonal event'), priced at the PUBLISHED Zonal Operating Reserve Demand Curve (BPM-002 \u00a75.2.1.2 / Schedule 28-A: 20% @ $200, 70% @ $1,100, 10% @ $3,300 = VOLL - zonal reg proxy). Zero residual-fitted parameters. Gate 4 PARTIAL: the zonal family FIRES (reserve dual nonzero 266/287/875 h in 2023/24/25 \u2014 right year ordering, 2025-concentrated) but prices at re-dispatch opportunity cost ($8-21/MWh max), never at the curve steps: the LP always clears the requirement by re-dispatch, so the >$200 scarcity tail stays 0 h vs actual 30/37/88 and CT_PEAKER (5.0/8.4/8.8 TWh) / 2025 coal (212 TWh) are unchanged. Fit is unchanged vs miso-35 (mean LMP 28.65/26.06/34.74; duration-curve max lifts 54.5/62.0/70.4); keeper because strictly more structurally faithful (real co-opt + real zonal curve). Residual root cause is NOT missing reserve structure \u2014 perfect-foresight headroom; next levers: sub-shortage opportunity-cost band (per-gen ramp rows, memory-infeasible at plant scale) or the D6 per-hub LMP scoring once uploaded. GATE 2 SCORED vs D6 hub actuals (2026-07-02, docs/multi-iso/miso-zonal-gate2.md): PARTIAL/FAIL/PARTIAL. The South-below-Midwest sign is REAL (actual RT S-minus-Midwest -2.39/-3.20/-4.96 vs model -1.09/-0.55/-0.32) and RDT S->N binding hours carry real timing skill vs actual South-cheapest hours (lift 1.5-2.4x, precision to 92%) \u2014 but the five Midwest zone means are identical to the cent (pairwise mean-order agreement 10/5/5 of 15; the actual Indiana/East premium and the high-wind West discount, W-E -5 to -7, are absent), spread-duration is 1-2 orders under on every tier even vs DA, and the non-RDT CIL/CEL groups mostly bind DEGENERATELY (West CIL at cap 1152/238/661 h with $0 price effect). Root cause: LOLE island envelopes are adequacy-scale quantities, an order of magnitude above where real Midwest flowgates (MWEX, IN->MI, WUMS) price; next levers are published flowgate limits on L1-L6, the D1 Michigan split, and marginal-loss factors. Keeper standing unchanged (no more-faithful run exists; nothing tuned to the residual).", "file": "frontend/data/backcast/runs/2026-07-02-miso-38-zonal-reserves.js", "id": "2026-07-02-miso-38-zonal-reserves", "iso": "MISO", "label": "miso 38 zonal reserves", "shorthand": "miso-38-zonal-reserves", "years": [2023, 2024, 2025]}, {"date": "2026-07-03", "definition": "STALE vs current CAISO keeper 2026-07-06-caiso-58-v2-regate (bundle caiso58_v2_regate) \u2014 this probe replays the superseded caiso51_firm_base (caiso-51-firm-base) keeper. Superseded in turn by 2026-07-05-caiso-statmode-d7-r2 (R2 CO2-basis re-solve) and 2026-07-06-caiso51-statmode-v2, but neither of those is a same-SHA replay of caiso-58-v2-regate either (G-10, statistical-mode-results-2026-07.md CAISO stale-box) \u2014 a fresh keeper-matched replay is queued, not done here. Retained for history. Original definition: D-7 statistical-mode A/B probe: byte-faithful replay of keeper caiso51_firm_base (meta.json) with every per-hour/per-year answer-injection overlay off (outage_source=statistical, ct_deployment_overlay=False, reliability_deployment_overlay=False, wefor_residual/groups=None, coal_plant_monthly_pricing=False). Structural model + realized annual Henry Hub gas price unchanged. Probe only \u2014 not a keeper, per CLAUDE.md #1/#13.", "file": "frontend/data/backcast/runs/2026-07-03-caiso-statmode-d-7.js", "id": "2026-07-03-caiso-statmode-d-7", "iso": "CAISO", "label": "caiso statmode d 7", "shorthand": "caiso-statmode-d-7", "years": [2023, 2024, 2025]}, {"date": "2026-07-03", "definition": "MISO 39 (KEEPER): miso-38 + 10-MINUTE RESERVE DELIVERABILITY (--miso-reserve-pergen): per-asset reserve columns at (zone, fuel-class) pooling (30 R columns/h; the documented 15 GB memory tier \u2014 per-plant is memory-infeasible at MISO scale), joint sum P + R <= sum pmax*availability per pool-hour, R capped at the availability-scaled 10-min class ramp (FleetArrays.ramp10 = NREL/TP-5500-55588 ramp rates x pmax: coal 0.15, CC 0.40, CT/oil 1.00, ST-gas 0.20; hourly, so CAMPD-outaged units contribute no ramp). Reserve now competes with energy on the marginal pool AND cleared reserve is bounded by what converts to energy inside MISO's 10-minute contingency window (BPM-002) \u2014 the deliverability structure the miso-38 gate-4 diagnosis named. Zero residual-fitted parameters. RESULT (gate 4 CLOSED-NEGATIVE, empirical): the >$200 tail stays 0 h vs actual 30/37/88 \u2014 the bind-gate predicted South deliverable-reserve shortfalls in 59/63/207 h (hitting 28/38 of 2025's actual DA-tail hours), but the perfect-foresight LP relieves every one by re-dispatch/import re-timing at <= $23/MWh (South thermal trim ~100 MW mean in the 207 reserve-active 2025 h); the zonal family fires MORE (59/64/207 h nonzero vs 37/41/125, max $11/$11/$23 vs $8/$11/$21) but never reaches the $200 step. Fit/volumes byte-comparable to miso-38 (mean LMP 28.62/26.04/34.74; CT_PEAKER 4.96/8.43/8.79 TWh; all deltas <0.05 TWh). KEEPER because strictly more structurally faithful (real deliverability rule added, nothing removed, nothing tuned). CONCLUSION for the tail residual (docs/multi-iso/miso-scarcity-tail-diagnosis.md): 2023's tail is 100% single-hour RT transients (DA median $40 in those hours, DA tail 1 h) \u2014 out of hourly-deterministic representation; the DA-visible part (1/24/38 h) needs the commitment-posture workstream (perfect-foresight re-timing is the binding relief channel) and/or a Midwest locational family for the 2024 Winter Storm Heather block; no admissible supply-side reserve structure can price it at this resolution. Determination NOT-YET (C1 2024 CC/CT, C2 2025 coal +10.4%, C3 price level -8.5/-13.6/-16.9% \u2014 all pre-existing, unchanged vs miso-38).", "file": "frontend/data/backcast/runs/2026-07-03-miso-39-reserve-pergen.js", "id": "2026-07-03-miso-39-reserve-pergen", "iso": "MISO", "label": "miso 39 reserve pergen", "shorthand": "miso-39-reserve-pergen", "years": [2023, 2024, 2025]}, {"date": "2026-07-03", "definition": "(PROBE) Cross-ISO band de-leakage (audit C-11/C-13, rule #24): MISO's inherited ERCOT gas bands (CC_CHP, CT_CHP, ST_GAS, and the CT_PEAKER committed 1.55 / econ 1.27/1.98 'generic shape') are neutralized to 1.0; MISO-grounded CC_REGULAR (committed 1.20 part-load premium, flat 0.95/1.08 baseload econ), the MISO offer-cap CT peak 4.0, and the physical F-class CC duct-burner peak 2.25 are kept; *_INTERMEDIATE (measured-shape) and coal untouched. EFFECT vs keeper miso-39 (not re-tuned, rule #1): dropping the ERCOT 1.55 CT start-hurdle to 1.0 lets peakers run, so the CT_PEAKER under-run SHRINKS -20.5->-12.0 TWh (2023) / -18.2->-9.2 (2024); the cheaper neutral bids lower C3a mean LMP to -9.8/-15.7/-19.6% (was -8.5/-13.6/-16.9%). PRE-EXISTING MISO root causes unchanged by this scrub: the CC_REGULAR +44 TWh over-run (measured-flat econ body) and the 0-hour scarcity tail (missing RDC/ELMP co-opt) \u2014 both open items, not band-addressable.", "file": "frontend/data/backcast/runs/2026-07-03-miso-40-band-deleak.js", "id": "2026-07-03-miso-40-band-deleak", "iso": "MISO", "label": "miso 40 band deleak", "shorthand": "miso-40-band-deleak", "years": [2023, 2024, 2025]}, {"date": "2026-07-03", "definition": "STALE vs current MISO keeper 2026-07-06-miso-44-wefor-neutral (bundle MISO/miso_44_wefor_neutral) \u2014 this probe replays the superseded miso_39_reserve_pergen (miso-39-reserve-pergen) keeper, itself superseded once already (miso-41-ct-evening, 2026-07-05) before the current swap. No successor statmode probe has been registered against any later MISO keeper (G-10 gap register: 'PJM/MISO statmode twins stale after 07-05 keeper swaps, unflagged') \u2014 a fresh same-SHA replay against miso_44_wefor_neutral is queued, not done here. Retained for history. Original definition: D-7 statistical-mode A/B probe: byte-faithful replay of keeper miso_39_reserve_pergen (meta.json) with every per-hour/per-year answer-injection overlay off (outage_source=statistical, ct_deployment_overlay=False, reliability_deployment_overlay=False, wefor_residual/groups=None, coal_plant_monthly_pricing=False). Structural model + realized annual Henry Hub gas price unchanged. Probe only \u2014 not a keeper, per CLAUDE.md #1/#13.", "file": "frontend/data/backcast/runs/2026-07-03-miso-statmode-d-7.js", "id": "2026-07-03-miso-statmode-d-7", "iso": "MISO", "label": "miso statmode d 7", "shorthand": "miso-statmode-d-7", "years": [2023, 2024, 2025]}, {"date": "2026-07-04", "definition": "(PROBE) caiso 53 lever-ab: tests the two FINDING-caiso-evening-merit levers on the full caiso-51 recipe. LEVER A (offer physics): CC_REGULAR/CC_CHP committed band 0.90/0.92x -> 1.00x plant-avg HR \u2014 the min-stable-load block's SRMC floor; restores committed >= econ_low ordering (econ_low held at the CAMPD-measured 0.95/0.96). LEVER B (measured market input): firm import-tranche VOLUMES grounded on DMM Annual Report RA-import capacity (CAISO BAA boundary: 2,323 MW 2023 / 3,371 MW 2024 / 2025 carries 2024 \u2014 open gap until the DMM 2025 annual report) split by published MIC branch-group share north/south of Path 15: per-year firm blocks 1072/1251, 1558/1813, 1566/1805 MW (was uncited 800/1800). RESULTS vs keeper caiso-51 \u2014 the targeted CC/import complex improves: C1 2023 CC_REGULAR now PASSES (was +4.91 TWh), 2024 +9.43 TWh (was +10.86); net import 2024 30.0 vs 32.4 TWh actual (was 25.8), 2025 38.0 vs 36.2 (was 32.3); evening corridors net-IMPORT (DSW +1213 / PNW +543 MW h15-21; the evening-export artifact is gone); C5a 2024 passes (was +8.5%); C7 CT diurnal largely fixed \u2014 2023+2024 CT_PEAKER pass, flat-floor CV signature 0.03-0.06 -> 2.6-3.1 (2025 CT fails on profile r 0.682 only; ST_GAS 2024/2025 still fail). The flagged price tension lands as expected: C3a worsens to +22.3/+37.9/+48.9% (Lever A reprices the committed band), C3b 0.303/0.488/0.502, C2 2025 gas +10.5% (was +8.1%). NEW ROOT-CAUSE ITEMS (logged, not chased): (1) 2023 C3c tail 454h >$200 vs 21h actual \u2014 Jan-2023-concentrated (513/525h): the measured $28/MMBtu citygate spike x the repriced committed CC (~$213) now crosses $200 while actual held below \u2014 monthly-average gas overlay too blunt in spike months and/or missing demand response; (2) C8 CT forced share 65-76% (was 29-33% lower-bound): forced TWh is flat (~all ct_netload_drag, 1.17-1.29 TWh) but MERIT CT energy collapsed 2.3 -> 0.6 TWh as grounded imports displace marginal CT \u2014 the drag floor now IS the CT class, confirming the FINDING's structural ramp/local gap (separate session; no floor may close it, rules #1/17-20). NOT promoted: C7 improves but C8's gated share worsens \u2014 does not beat caiso-51 on C7/C8 jointly. Both levers are grounded inputs (rule #15) and stay in code; caiso-51 remains keeper. DOF ledger: +cc_committed_hr_mult_floor (measured-physical), +caiso_firm_import_volumes (measured-market); IMPORT_TRANCHES firm volumes re-identified, n_residual 8 -> 7.", "file": "frontend/data/backcast/runs/2026-07-04-caiso-53-lever-ab.js", "id": "2026-07-04-caiso-53-lever-ab", "iso": "CAISO", "label": "caiso 53 lever ab", "shorthand": "caiso-53-lever-ab", "years": [2023, 2024, 2025]}, {"date": "2026-07-04", "definition": "(PROBE, INERT) Component A: winter (Nov-Mar) oil-burn inventory budget (start_fill 2.8M bbl WRP-low, +2 refills, pooled fleet row, MMBtu-weighted, dual-fuel limb gated to oil-switch hours), on top of the measured daily AGT basis. RESULT: byte-identical to the daily-basis-only twin (oil 0.35/0.23/1.47 TWh, 0 h >$300) \u2014 the ~1.5 TWh seasonal inventory never binds even with heavy oil dispatch (Jan-2025 oil 0.755 TWh < 0.91 TWh/month cap). Component A adds nothing; not tuned to force binding (rule #1). Negative result.", "file": "frontend/data/backcast/runs/2026-07-04-neiso-inventorycap-inert-probe.js", "id": "2026-07-04-neiso-inventorycap-inert-probe", "iso": "NEISO", "label": "neiso inventorycap inert probe", "shorthand": "neiso-inventorycap-inert-probe", "years": [2023, 2024, 2025]}, {"date": "2026-07-05", "definition": "(PROBE) caiso 54 daily-gas: caiso-53 recipe + --gas-hub-basis-daily, testing the caiso-53 root-cause item that the MONTHLY-average SoCal/PG&E citygate gas overlay is too blunt in spike months. Intakes daily CA Composite Average citygate spot (EIA NG Weekly compact table, 2023-2025, scripts/fetch_caiso_citygate_daily.py) and replaces the flat monthly hub level with a true-calendar-dated daily shape, mean-preserving on the measured monthly basis (annual gas burn/fuel mix unchanged) -- same construction as the NYISO daily Transco leg (dense trading-day quotes), not NEISO's sparse-narrative one. RESULT (official C3c, ordc.hoursGt200, same-environment A/B vs a fresh caiso-53 reproduction): 2023 454h(monthly)->455h(daily) vs 21h actual -- essentially UNCHANGED, NOT the collapse hypothesized. Day-level attribution explains why: the daily series correctly REDISTRIBUTES the tail rather than shrinking it. The measured citygate genuinely collapsed only in the LAST WEEK of Jan-2023 ($7.80-11.50/MMBtu) -- those days correctly drop from 9-19 tail-hours/day to ZERO. But days 2-18 (measured $16-24/MMBtu) are ABOVE the monthly average once the cheap last week is excluded, so they gain tail-hours instead (max zonal LMP $219.9->up to $282.9). Net Jan effect ~505->489h (own recompute), a real but marginal ~3% reduction. CONCLUSION: the monthly-average blunting is a real, now-fixed defect (last week was wrongly priced high before), but it is NOT the primary driver of the ~450h-vs-21h over-prediction -- most of January 2023 was persistently elevated in the real citygate market, not spike-concentrated in a way a monthly average would blunt. NEW ROOT-CAUSE ITEM (logged, not chased): the dominant driver of the residual ~450h/21h gap is something else -- CT_PEAKER's ct_netload_drag floor (forced share 40-62% per this bundle's D-2) and/or ra_mustoffer_bridge are candidates, or a genuine actual-side effect (demand response / oil-switching / imports) the model lacks; investigate separately per rule #1, no floor forcing. The daily-basis input is kept in code on its own physical merits (correct day-to-day delivered fuel cost, rule #13) independent of whether it moves C3c -- a real market behaviour is not reverted because the residual didn't move (rule #1). Not promoted; caiso-51/caiso-53 remain keeper. legitimacy_diagnostics attached (D-5 caiso_ra_mustoffer gap is pre-existing/documented on caiso-53 already, not introduced here).", "file": "frontend/data/backcast/runs/2026-07-05-caiso-54-daily-gas.js", "id": "2026-07-05-caiso-54-daily-gas", "iso": "CAISO", "label": "caiso 54 daily gas", "shorthand": "caiso-54-daily-gas", "years": [2023, 2024, 2025]}, {"date": "2026-07-05", "definition": "PROBE (W3-P2 caiso-52-ct-scrub HEAD verification; keeper stays caiso-51). Byte-faithful replay of the caiso-51 keeper config at HEAD (2026-07-05), all years \u2014 the CT-floor scrub is already merged in source, so this zero-delta replay exercises the scrubbed dispatch path and closes the flagged keeper-reproducibility 'drift'. The audit's three stacked CAISO CT forcing engines are gone, defended at three code layers: (1) reliability_floor_coeffs_CAISO.csv CT limbs windowed 15-21 then enabled=False; (2) drop_drag_owned_reliability_specs drops every CT_PEAKER limb whenever ct_netload_drag is on (rule 19); (3) RA startup bridge gated on min_down>=RA_BRIDGE_ECON_MIN_DOWN_HOURS (4h), so fast-start CTs (min-down 1h) are never economically bridged (rule 17). Result at HEAD: CT_PEAKER now a SINGLE windowed mechanism (ct_netload_drag; RA-bridge CT share <0.4% all years), D-4 off-window 0% (was ~62-66% in caiso-42), D-1 CT off-peak CV ratio 3.05-3.52 (was 0.000 flat-floor signature). Reproduces committed caiso-52 (CT 2.12/1.73/1.30 vs 1.97/1.56/1.15 TWh); the 'drift' (CT ~3.4->~1.7 TWh vs the pre-scrub keeper) IS the scrub effect, not a bug. Still open (NOT closable by a floor scrub, rule 1): D-2 CT forced share 60/67/69% > 10% = the evening-merit structural gap (CT thermodynamically dominated by CC in an energy-only zonal LP; FINDING-caiso-evening-merit \u2014 needs ramp/min-up-down + sub-zonal LA-basin structure, do NOT re-floor); D-5 caiso_ra_mustoffer w2 forecast-parity wiring gap; ST_GAS D-1 shape (pre-existing). capacity_deliverability_limits records True but no-ops (clean CAISO partition absent) so dispatch is faithful to caiso-51; MIC seam limit carried by caiso_per_hub_intertie.", "file": "frontend/data/backcast/runs/2026-07-05-caiso-55-ct-scrub.js", "id": "2026-07-05-caiso-55-ct-scrub", "iso": "CAISO", "label": "caiso 55 ct scrub", "shorthand": "caiso-55-ct-scrub", "years": [2023, 2024, 2025]}, {"ablation_twin": "Reference (limb-ON) half of the B-LIMB-1 A/B; not itself a probe subject.", "date": "2026-07-05", "definition": "(PROBE) B-LIMB-1 same-env baseline: caiso-51-firm-base on current main with the SP15/CC_REGULAR tmax reliability-floor limb ON (original CSV). Limb-ON reference for the caiso-r1-signflip-off probe; the two isolate the R1 disablement (\u0394\u22480, floor non-binding). Also documents caiso-51 keeper drift on current main: CT_PEAKER total ~1.7 TWh / C8 forced-share 60-71% vs the committed bundle's ~3.4 TWh / 27-33% (separate root-cause item).", "file": "frontend/data/backcast/runs/2026-07-05-caiso-r1-baseline-limb.js", "id": "2026-07-05-caiso-r1-baseline-limb", "iso": "CAISO", "label": "caiso r1 baseline limb", "market_story": "Re-solving the caiso-51 keeper config on current main (limb ON) reproduces CC_REGULAR, price and CO2 within ~1% of the committed bundle but shows CT_PEAKER energy roughly halved and its C8 forced-share doubled \u2014 a keeper-reproducibility drift independent of B-LIMB-1, flagged for the CAISO owner.", "shorthand": "caiso-r1-baseline-limb", "years": [2023, 2024, 2025]}, {"ablation_twin": "D-3 zero-forcing twin deferred: the as_zero_forcing_ablation / --zero-forcing-ablation mechanism (B-DIAG-1) has not landed yet. The 2026-07-05-caiso-r1-baseline-limb run is the same-env limb-ON reference for isolating this mechanism change; register the D-3 twin once B-DIAG-1 lands.", "date": "2026-07-05", "definition": "(PROBE) B-LIMB-1 R1: caiso-51-firm-base with the unidentified sign-flip temperature-CF limb SP15/CC_REGULAR tmax DISABLED (D-8 \u00a72B: Spearman \u03c1 +0.69\u2192\u22120.10 train\u2192holdout; decision rule R1, CLAUDE.md rule 17). Same-env A/B vs the caiso-r1-baseline-limb run shows the limb was NON-BINDING: CC_REGULAR \u0394\u22640.018 TWh, CT_PEAKER/ST_GAS \u0394\u22480, price/CO2/forced-share identical \u2014 removing the unidentified floor costs ~0 dispatch. Structural change judged on identification, not fit (rule #1).", "file": "frontend/data/backcast/runs/2026-07-05-caiso-r1-signflip-off.js", "id": "2026-07-05-caiso-r1-signflip-off", "iso": "CAISO", "label": "caiso r1 signflip off", "market_story": "The SP15/CC_REGULAR tmax reliability floor was the only live limb of the three B-LIMB-1 sign-flip limbs (PJM ComEd and CAISO SP15/ST_GAS already shipped disabled). In the caiso-51 dispatch CAISO gas-CC clears economically well above the floor's min-stable level on hot SP15 days, so the floor never bound; disabling it (R1) shifts <0.03% of CC energy. The floor was unidentified scaffolding doing no structural work \u2014 R1's best case. NOTE: the large apparent CT_PEAKER shrink vs the COMMITTED caiso-51 bundle is main-drift since 2026-07-03 (see baseline run), not this change.", "shorthand": "caiso-r1-signflip-off", "years": [2023, 2024, 2025]}, {"date": "2026-07-05", "definition": "STALE vs current CAISO keeper 2026-07-06-caiso-58-v2-regate (bundle caiso58_v2_regate) \u2014 this r2 re-solve only addressed the R2 physical-HR CO2-basis confound on top of the superseded caiso51_firm_base (caiso-51-firm-base) keeper; it is not a same-SHA replay of the current keeper (G-10 gap register: 'CAISO/NYISO r2 confounded with offer-curve merges, no same-SHA keeper replay'). 2026-07-06-caiso51-statmode-v2 is a later probe but is also still on the caiso51_firm_base basis. A fresh replay against caiso58_v2_regate is queued, not done here. Original definition: D-7 statistical-mode A/B probe: byte-faithful replay of keeper caiso51_firm_base (meta.json) with every per-hour/per-year answer-injection overlay off (outage_source=statistical, ct_deployment_overlay=False, reliability_deployment_overlay=False, wefor_residual/groups=None, coal_plant_monthly_pricing=False). Structural model + realized annual Henry Hub gas price unchanged. RE-SOLVED at HEAD (2026-07-05) superseding the 2026-07-03 probe: the R2 physical-HR CO2 basis (fff2c34) moves CAISO's merit order. Probe only \u2014 not a keeper, per CLAUDE.md #1/#13.", "file": "frontend/data/backcast/runs/2026-07-05-caiso-statmode-d7-r2.js", "id": "2026-07-05-caiso-statmode-d7-r2", "iso": "CAISO", "label": "caiso statmode d7 r2", "shorthand": "caiso-statmode-d7-r2", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-06-miso-41-ct-evening-ablation", "date": "2026-07-05", "definition": "MISO 41 (KEEPER, supersedes miso-39): miso-40 de-leaked offer curve (neutral 1.0 generic gas bands, no inherited ERCOT multipliers) + CT_PEAKER reliability-floor EVENING WINDOW [15,21]. Fixes the C7/rule-13 D-4 failure carried by miso-39: the hot-day (tmax) CT reliability limb was floored a flat 38 MW in all 24 h (68-70% off-window, binding overnight when CT CF~0) because the MISO limb carried no sub-daily window; adding start_hour=15/end_hour=21 (matching the D-4 justified window [15,22) and the CAISO CT limbs) gates it to the afternoon-evening net-load ramp. RESULT: legitimacy diagnostics flip Overall FAIL->PASS (D-4 CT_PEAKER 0% off-window all 3 yrs; D-1/D-2/D-5/D-9 hold); zero new fitted parameter (the window is a structural shape param, derive-script-emitted). Mean LMP 28.67/25.99/34.47 (2023/24/25); vs miso-39 29.10/26.60/35.59 the de-leak trims prices ~0.4-1.1/MWh so C3a is modestly worse (-9.8/-15.6/-19.5% vs -8.5/-13.6/-16.9%), CO2 PASS x3 and the 0-h scarcity tail (C3c) unchanged. PROMOTED because strictly more structurally faithful: it clears a HARD legitimacy gate the incumbent violates (a rule-13 off-window floor) and removes the foreign ERCOT band leak, nothing tuned. OPEN ROOT CAUSES (logged, not fixed - rules #1/#11, results/calibration/FINDING-miso-burndown-2026-07.md): (A) coal (marginal ~94% of hours) is offered ~$4-5/MWh BELOW its measured F923 delivered SRMC by the gas-keyed passthrough sigmoid (model LMP $25.9 < coal committed measured SRMC $28.3 < actual $30.8 = coal econ_body measured $30.4), driving both the coal over-run (C1/C2) and the low price (C3a) - needs a measured take-or-pay-grounded bound on the marginal coal tranche, not a residual re-tune; (B) missing RDC/ELMP scarcity price (C3c). The neutral-1.0 gas committed bands sit AT the 1.0x SRMC floor (no rule-17 violation) and are immaterial since gas is never marginal - MISO does not need grounded gas bands as the burndown lever.", "file": "frontend/data/backcast/runs/2026-07-05-miso-41-ct-evening.js", "id": "2026-07-05-miso-41-ct-evening", "iso": "MISO", "label": "miso 41 ct evening", "market_story": "The evening-window CT_PEAKER reliability floor forces only 0.02-0.08 TWh/yr (<0.35% of the class) \u2014 a real but small hot-day evening-ramp reliability commitment, not a residual-buying floor. Zero-forcing every merchant floor confirms this directly: CT_PEAKER dispatch RISES 3.2/3.8/4.7% (2023/24/25) once the floor is removed, because it stops competing with floor-forced baseload for the same net-load hours, not falls, as a residual-buying floor would show. ST_GAS more than doubles (+63-115%) once other floors stop consuming load ahead of it. OTHER_FOSSIL's entire keeper volume (4.0/3.7/2.5 TWh/yr) disappears in the twin \u2014 that class is currently 100% floor-forced, an open root-cause item (rules #1/#11) to isolate, not fixed here. Coal subtypes and CC_REGULAR/CC_CHP move by <1.5%, confirming the keeper's floors are immaterial to the coal-vs-gas merit order the burndown finding (FINDING-miso-burndown-2026-07.md) already attributes to the passthrough-sigmoid offer curve, not to any floor.", "shorthand": "miso-41-ct-evening", "years": [2023, 2024, 2025]}, {"date": "2026-07-05", "definition": "(CONTROL) A/B baseline for the neiso-48 CT-floor scrub: the identical neiso-47 recipe on current main with the two all-24h CT_PEAKER tmax reliability-floor limbs still ON. Documents the pre-scrub failing state the keeper removes \u2014 D-4 off-window binding 72-76% and C8 CT_PEAKER forced-energy share 0.47/0.78/0.47 (2023/24/25, gate <0.10). Not a keeper candidate; reference half of the neiso-48-ct-floor A/B.", "file": "frontend/data/backcast/runs/2026-07-05-neiso-48-base-control.js", "id": "2026-07-05-neiso-48-base-control", "iso": "NEISO", "label": "neiso 48 base control", "shorthand": "neiso-48-base-control", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-05-neiso-48-ct-floor-ablation", "date": "2026-07-05", "definition": "KEEPER (promoted 2026-07-05, replacing neiso-47): the neiso-47 fast-start keeper recipe on current main with ONE structural change \u2014 the two all-24h CT_PEAKER temperature (tmax) reliability-floor limbs (Boston, Connecticut) SCRUBBED (enabled False in reliability_floor_coeffs_NEISO.csv), a zero-parameter mechanism deletion mirroring the caiso-52 CT scrub and the pjm-77 reconcile. Root cause (rules 17/18): the limbs carried no sub-daily window, so on any design-cooling day they forced fast-start CTs at min-stable for ALL 24 h; A/B vs the same-recipe control (neiso-48-base-control, bundle neiso_ctbase) shows D-4 off-window binding 72-76% -> floor removed, C8 CT_PEAKER forced-energy share 0.47/0.78/0.47 -> 0.00 all years, C7 off-peak CV ratio 0.65/0.63/0.59 -> 0.76/0.86/0.79. Disclosed cost (rule #1, NOT to be won back with a floor): CT_PEAKER grid volume falls to 0.010/0.021/0.099 TWh, absorbed by marginal CC_REGULAR at essentially the same price (dw-LMP +$0.02-0.06); every other class moves <0.0012 TWh. Remaining open C7 gate is ST_GAS diurnal shape (pre-existing in neiso-47, unchanged here) \u2014 the next NEISO root cause. Still NOT-YET. Promoted as the most structurally faithful NEISO run (rules #1/#12): one confirmed flat-floor bug removed, nothing tuned.", "file": "frontend/data/backcast/runs/2026-07-05-neiso-48-ct-floor.js", "id": "2026-07-05-neiso-48-ct-floor", "iso": "NEISO", "label": "neiso 48 ct floor", "market_story": "ISO-NE fast-start peakers are economically dispatched for the afternoon/evening peak, not day-ahead committed at a floor: on hot days the real Boston/Connecticut CT fleet is near-zero overnight. The scrubbed all-24h limbs were forcing roughly half of the (tiny) CT_PEAKER class energy at binding floors and flattening its off-peak profile; removing them restores the spiky peaker signature while the marginal CC block absorbs the ~0.07-0.12 TWh/yr at the same clearing price.", "shorthand": "neiso-48-ct-floor", "years": [2023, 2024, 2025]}, {"date": "2026-07-05", "definition": "(D-3 zero-forcing ablation twin of neiso-48-ct-floor, bundle neiso_ctscrub) every MERCHANT floor/bridge/drag off via ScenarioConfig.as_zero_forcing_ablation (off-list from the D-2 mechanism registry), structural protected set kept (nuclear must-run, CHP steam, coal take-or-pay, measured biomass/OTHER must-run). Exact neiso-48 config/span (2023-2025, P1+P2). Registered per CLAUDE.md rule 20 so the keeper-vs-twin per-class delta is on the dashboard; not a keeper candidate.", "file": "frontend/data/backcast/runs/2026-07-05-neiso-48-ct-floor-ablation.js", "id": "2026-07-05-neiso-48-ct-floor-ablation", "iso": "NEISO", "label": "neiso 48 ct floor ablation", "shorthand": "neiso-48-ct-floor-ablation", "years": [2023, 2024, 2025]}, {"date": "2026-07-05", "definition": "HEAD re-gate (calibration-complete checklist item 1): byte-faithful replay of neiso-48-ct-floor meta.json at HEAD, all keeper years in one invocation, verifying reproducibility across the 07-04 offer merges per the pjm-77/nyiso-48 pattern.", "file": "frontend/data/backcast/runs/2026-07-05-neiso-48-head-regate.js", "id": "2026-07-05-neiso-48-head-regate", "iso": "NEISO", "label": "neiso 48 head regate", "shorthand": "neiso-48-head-regate", "years": [2023, 2024, 2025]}, {"date": "2026-07-05", "definition": "STALE vs current NEISO keeper 2026-07-06-neiso-50-head-repro (bundle neiso49_resolve_confirm) \u2014 this r2 solve replays the neiso_ctscrub (neiso-48-ct-floor) keeper, since superseded twice (neiso-49-stgas-netload, then the current neiso-50-head-repro); it is not a same-SHA replay of the current keeper. A fresh replay against neiso49_resolve_confirm is queued, not done here. Original definition: D-7 statistical-mode A/B probe: byte-faithful replay of keeper neiso_ctscrub (the 2026-07-05 neiso-48-ct-floor keeper, meta.json) with every per-hour/per-year answer-injection overlay off (outage_source=statistical, ct_deployment_overlay=False, reliability_deployment_overlay=False, wefor_residual/groups=None, coal_plant_monthly_pricing=False). Structural model + realized annual Henry Hub gas price unchanged. RE-SOLVED at HEAD (2026-07-05) superseding the 2026-07-03 probe (which replayed the prior neiso-47 keeper): the R2 physical-HR CO2 basis (fff2c34) moves NEISO's merit order (carbon-priced ISO) so the prior solve was stale; C5a CO2 vs eGRID still PASSes (R2 effect on this ISO's CO2 verdict is near-zero, per docs/handoffs/co2-keeper-regate-2026-07-05.md). Probe only \u2014 not a keeper, per CLAUDE.md #1/#13.", "file": "frontend/data/backcast/runs/2026-07-05-neiso-statmode-d7-r2.js", "id": "2026-07-05-neiso-statmode-d7-r2", "iso": "NEISO", "label": "neiso statmode d7 r2", "shorthand": "neiso-statmode-d7-r2", "years": [2023, 2024, 2025]}, {"date": "2026-07-05", "definition": "(D-3 zero-forcing ablation twin of nyiso_deleak_ccecon) every MERCHANT floor off (NYISO material floor: nyiso_local_selfsupply), structural protected set kept (nuclear must-run, CHP steam, coal take-or-pay, firm imports). Mirrors run_calibration_full.apply_zero_forcing_ablation.", "file": "frontend/data/backcast/runs/2026-07-05-nyiso-47-ccdeleak-ablation.js", "id": "2026-07-05-nyiso-47-ccdeleak-ablation", "iso": "NYISO", "label": "nyiso 47 ccdeleak ablation", "shorthand": "nyiso-47-ccdeleak-ablation", "years": [2023, 2024, 2025]}, {"date": "2026-07-05", "definition": "(PROBE \u2014 D-2 ATTRIBUTION TWIN of nyiso-48-head-regate, NOT a keeper) HEAD code (git 8d46b90) + keeper-era _NYISO_OFFER_CURVE restored via --offer-curve-json (CT_PEAKER peak 13.15/econ_low 1.27/econ_high 1.98, CC_REGULAR econ_high 1.21, CT_CHP 1.10/1.20/1.20/1.40) \u2014 the ONE delta vs nyiso-48. Determination NOT-YET (governance UNATTESTED; C8 pre-existing floor forced-share). RESULT: restoring only the offer curve recovers BOTH regressions \u2014 C1 free-class 10/10 (vs 48's 9/10), C7 diurnal (D-1) PASS (vs 48's FAIL; CT_PEAKER off-peak CV ratio 1.08/1.20/1.24 all pass), CT_PEAKER back to 1.56/1.37/1.75 TWh and ST_GAS to 7.86/9.67/11.08 (vs 48's 4.46/4.51/4.73 and 6.15/7.58/9.30). CONCLUSION: the entire nyiso-48 C1/C7 regression is the B-NYI-1 _NYISO_OFFER_CURVE de-leak, not the emissions R2 basis, interchange unification, or any other post-07-03 HEAD merge (residual CT_PEAKER delta vs keeper's 1.82 is ~0.26 TWh, negligible). This probe is a DIAGNOSTIC ONLY \u2014 it re-arms the de-leaked rule-25 scalars and MUST NOT be promoted (rule #26). The grounded (de-leaked) offer stays; the fix is structural (LI/NYC delivered-fuel basis + #1344 reserve scarcity). Rules #1/#17/#25/#26.", "file": "frontend/data/backcast/runs/2026-07-05-nyiso-49-offer-ab.js", "id": "2026-07-05-nyiso-49-offer-ab", "iso": "NYISO", "label": "nyiso 49 offer ab", "shorthand": "nyiso-49-offer-ab", "years": [2023, 2024, 2025]}, {"date": "2026-07-05", "definition": "(PROBE \u2014 real partial structural fix, NOT a keeper swap; keeper stays nyiso-41 STALE-VS-HEAD.) nyiso-41 keeper config at HEAD (de-leaked offer curve, = nyiso-48 baseline) + the new NYISO downstate CT interruptible city-gate gas premium (nyiso_downstate_ct_gas_basis), one-delta vs nyiso-48-head-regate, all years 2023-2025. MECHANISM (candidate a, issue #1344 / B-NYI-1): each NYC/Long Island CT_PEAKER (LM6000) unit's delivered gas is lifted from the Transco Z6 NY pipeline hub to its LDC city-gate delivered index by the MEASURED monthly premium (EIA NG N3050NY3 NY city-gate minus the measured Transco Z6 NY hub, floored 0; positive year-round mean ~$2.7/MMBtu, summer-peaked to ~$5). A rule-13 delivered fuel price: non-firm downstate peakers buy interruptible city-gate gas, so an HR~9-10 LM6000 no longer undercuts the HR~11-12 downstate steam fleet on flat hub gas. RESULT: CT_PEAKER 4.46/4.51/4.73 (nyiso-48) -> 3.26/4.20/4.03 TWh (actual 2.26/2.13/2.84); C1 CT_PEAKER FAIL->PASS 2023(+1.00)/2024(+2.06 TWh, in the +-2.94 band). C1 free-class stays 9/10 (remaining free fail = 2024 ST_GAS -3.39, the pre-existing steam/gas-total under-run, unchanged by the premium). C2/C4/C5a PASS. LIMITS (why still NOT a keeper): C7 (D-1) 2024 CT_PEAKER stays FAIL (off-peak cv_ratio 0.454->0.418<0.5) and C3a stays -17/-18/-15%. ROOT CAUSE of the residual: the LI CT over-run is DOMINATED by the Long Island local self-supply floor + CT temperature reliability floor forcing flat in-pocket LM6000 baseload (a fuel-cost premium cannot reduce floor-forced volume or restore diurnal peakiness), and the C3a under-price is the missing peaker competitive-scarcity / #1344 reserve-RCPF price structure (the reserve co-opt is present but binds only ~1000-2500 zone-hrs vs measured ~3000-4000). Candidate b (reserve/RCPF) EVALUATED: the published-tariff RCPF locational families are already in the LP (energy_reserve_coopt on) and cited, but confirmed non-binding with grounded static requirements (consistent with nyiso-29/30/31); the dearer downstate gas does not make them bind. The delivered-fuel basis is a validated, grounded, forward-reproducible structural input kept default-off; the residual is the floor re-derivation (rule #23, now that the basis has landed) + #1344. Rules #1/#3/#13/#26.", "file": "frontend/data/backcast/runs/2026-07-05-nyiso-50-downstate-ctgas.js", "id": "2026-07-05-nyiso-50-downstate-ctgas", "iso": "NYISO", "label": "nyiso 50 downstate ctgas", "shorthand": "nyiso-50-downstate-ctgas", "years": [2023, 2024, 2025]}, {"date": "2026-07-05", "definition": "(PROBE \u2014 NOT a keeper swap) NYISO CT/ST reliability-floor re-derivation (rule 17/18/23), floors-alone config; one-delta vs nyiso-48 head-regate, all years 2023-2025. Two source-grounded narrowings: (1) the NYC CT_PEAKER 24h hot step (tmax 31.7 / 0.1833) DISABLED (r1_disabled) \u2014 the D-4 off-window binder that double-floored NYC CT on top of the windowed NYC_CT_ev ramp and bound all 24h incl. overnight where measured CAMPD NYC CT CF~=0.018 (rule 17/18); (2) the Long Island local self-supply floor NARROWED to the HB14-21 peak window (its LCR/cable-import driver binds only at the summer design-cooling peak, not overnight) \u2014 the 0.45 fraction (residual-identified, issue #1345) is UNCHANGED, only the hours it binds. RESULT: C7 diurnal (D-1) FAIL->PASS all years (2024 CT_PEAKER off-peak cv_ratio 0.454 -> 2.393). CT_PEAKER 4.46/4.51/4.73 -> 3.70/2.84/3.86 TWh (actual 2.26/2.13/2.84), C1 CT_PEAKER FAIL->in band; free-class stays 9/10 (remaining fail = 2024 ST_GAS -3.48, the pre-existing steam under-run). self-supply CT forcing HALVED (1.84/2.87/1.86 -> 0.90/1.23/0.89 TWh); reliability-floor CT overnight energy = 0.000 (was ~0.18 from the NYC step). NOT a keeper: rule-20 D-2 CT_PEAKER forced-share still >10% (reliability alone 25.6/34.1/25.1%) and C3a -16.2/-15.5/-13.6% / C3c 0/0/7h still FAIL \u2014 both now cleanly the missing #1344 peaker-scarcity/reserve price structure (CT peakers stay economically idle without it, so the floors carry the CT commitment). D-4 residual (~35%) is entirely hour 14 (0 overnight) \u2014 a boundary artifact between D-4's hardcoded canonical CT window h15-21 and the source-derived NYISO ramp HB14-21. Rules 1/17/18/23; #1344 out of scope (parallel LP-core refactor).", "file": "frontend/data/backcast/runs/2026-07-05-nyiso-51-floor-rederive.js", "id": "2026-07-05-nyiso-51-floor-rederive", "iso": "NYISO", "label": "nyiso 51 floor rederive", "shorthand": "nyiso-51-floor-rederive", "years": [2023, 2024, 2025]}, {"date": "2026-07-05", "definition": "(PROBE \u2014 KEEPER-CANDIDATE pending #1344, NOT a keeper swap) NYISO CT/ST reliability-floor re-derivation (rule 17/18/23) + nyiso_downstate_ct_gas_basis=True (the PR #1427 delivered-fuel city-gate premium, kept default-off); one-delta vs nyiso-48 head-regate + the floors config, all years 2023-2025. Floors: NYC CT 24h hot step DISABLED (r1_disabled, D-4 off-window binder) + LI local self-supply NARROWED to the HB14-21 peak window (0.45 level unchanged; hours only). RESULT: strongest candidate yet. CT_PEAKER 4.46/4.51/4.73 -> 2.02/2.33/2.91 TWh (actual 2.26/2.13/2.84) \u2014 near-exact all 3 years; C1 CT_PEAKER in band, free-class 9/10 (remaining fail = 2024 ST_GAS -3.30, the pre-existing steam under-run). C7 diurnal (D-1) PASS all years (2024 CT_PEAKER off-peak cv_ratio 0.454 -> 3.47, r 0.84). self-supply CT forcing halved; reliability-floor CT overnight energy = 0.000. NOT YET a keeper: rule-20 D-2 CT_PEAKER forced-share still >10% (reliability alone 45.8/54.5/39.3% \u2014 HIGHER share because the dearer downstate gas shrinks the economic-CT denominator) and C3a -13.5/-14.7/-12.5% (improved from -17/-18/-15 by the gas premium, still out of band) / C3c 0/0/7h \u2014 both now cleanly the missing #1344 peaker-scarcity/reserve price structure, the SAME root cause (CT peakers stay economically idle without it, so the floors carry the CT commitment and the tail never prices). D-4 residual (~34%) is entirely hour 14 (0 overnight) \u2014 the h15-21 vs HB14-21 window-boundary artifact, not off-window binding. Recommended eventual NYISO keeper config once #1344 lands. Rules 1/13/17/18/23; keeper stays nyiso-41 STALE-VS-HEAD, keepers.json unchanged.", "file": "frontend/data/backcast/runs/2026-07-05-nyiso-52-floor-rederive.js", "id": "2026-07-05-nyiso-52-floor-rederive", "iso": "NYISO", "label": "nyiso 52 floor rederive", "shorthand": "nyiso-52-floor-rederive", "years": [2023, 2024, 2025]}, {"date": "2026-07-05", "definition": "STALE vs current NYISO keeper 2026-07-06-nyiso-53-li-tsl (bundle nyiso53_litsl_v2) \u2014 this r2 solve replays the superseded nyiso41_hubprices (nyiso-41-hub-prices) keeper; it addressed only the R2 CO2-basis confound (fff2c34) and the B-NYI-1 offer-curve de-leak, not the keeper swap to nyiso-53 (Zone-K LCR/TSL mechanism + v2 measured plant CO2 rates) \u2014 it is not a same-SHA replay of the current keeper (G-10 gap register: 'CAISO/NYISO r2 confounded with offer-curve merges, no same-SHA keeper replay'). A fresh replay against nyiso53_litsl_v2 is queued, not done here. Original definition: D-7 statistical-mode A/B probe: byte-faithful replay of keeper nyiso41_hubprices (meta.json) with every per-hour/per-year answer-injection overlay off (outage_source=statistical, ct_deployment_overlay=False, reliability_deployment_overlay=False, wefor_residual/groups=None, coal_plant_monthly_pricing=False). Structural model + realized annual Henry Hub gas price unchanged. RE-SOLVED at HEAD (2026-07-05) superseding the 2026-07-03 probe: the R2 physical-HR CO2 basis (fff2c34) moves NYISO's merit order (carbon-priced ISO) so the prior solve was stale; C5a CO2 vs eGRID still PASSes (R2 effect on this ISO's CO2 verdict is <0.1%, per docs/handoffs/co2-keeper-regate-2026-07-05.md). CAVEAT: this HEAD replay inherits the keeper's then-current offer state, including the B-NYI-1 `_NYISO_OFFER_CURVE` de-leak (CT_PEAKER peak 13.15->4.0, econ_low/econ_high 1.27/1.98->1.0/1.0; CC_REGULAR econ_high 1.21->1.0, merge a4c219e, 2026-07-05 re-gate) \u2014 recorded here, not compensated for; see docs/calibration-log.md 2026-07-05 NYISO keeper HEAD re-gate entry. Probe only \u2014 not a keeper, per CLAUDE.md #1/#13.", "file": "frontend/data/backcast/runs/2026-07-05-nyiso-statmode-d7-r2.js", "id": "2026-07-05-nyiso-statmode-d7-r2", "iso": "NYISO", "label": "nyiso statmode d7 r2", "shorthand": "nyiso-statmode-d7-r2", "years": [2023, 2024, 2025]}, {"date": "2026-07-05", "definition": "(PROBE, not a keeper swap) PJM-77 demand-repair re-gate under PR #1426 (repaired demand-profile clean datatype). pjm-77 is the ONLY keeper whose scored years read the corrupted legacy eia_demand_profiles file (PJM has no per-BA demand extract; CAISO/MISO/NYISO/NEISO/ERCOT read dedicated per-BA hourly extracts for 2023-2025). The corruption was a zero-sentinel run: 23h in 2023 (idx 7393-7415) and 22h in 2024 (idx 1659-1680) at raw_mw=0.0; 2025 was already clean. TWIN A (resolve): byte-faithful pjm-77 meta.json replay at HEAD with the repaired demand engaged. Result: reproduces the committed keeper verdict CRITERION-FOR-CRITERION (NOT-YET; C1/C2/C3/C8 FAIL, C4/C5a/C7 PASS unchanged) \u2014 the only movement is the C6 governance gate showing UNATTESTED, a pure replay artifact (this bundle lacks the keeper's calibration_attestation.json; the LP dispatch is unchanged). Numeric deltas are tiny and confined to the two corrupted years: gas +0.38/+0.58 TWh, coal +0.11/+0.12 TWh (+~0.15%), CO2 +0.26/+0.34 Mt, mean LMP within 0.03 $/MWh, 2025 exactly zero (in-bundle control). No gate flips. Conclusion (rule #14): the demand repair is IMMATERIAL to every PJM scored criterion; pjm-77 is verified demand-robust and stays the keeper (NOT swapped to this confounded HEAD re-solve, which also carries ~30 files of post-e9daf7e code merges and lacks the governance attestation + zero-forcing ablation twin a keeper requires). Attribution twin B (HEAD + corrupted demand, isolated data root) decomposes A-B (demand repair) vs B-keeper (code merges) in docs/calibration-log.md 2026-07-05.", "file": "frontend/data/backcast/runs/2026-07-05-pjm-78-demand-regate.js", "id": "2026-07-05-pjm-78-demand-regate", "iso": "PJM", "label": "pjm 78 demand-regate", "shorthand": "pjm-78-demand-regate", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "G-15 CT-drag D-8 closure: zero-drag ablation arm \u2014 single delta ct_netload_drag=false on the caiso-51 keeper config replayed at HEAD (3b31193). Byte-faithful otherwise (use_plant_emission_rates_v2 stays off exactly as the keeper ran). Measures what the evening net-load drag actually carries at HEAD, with the CT limbs retired (b3a9036) and the RA bridge physics-gated (916e8cb). Registered PROBE whatever the result (rules 15/16); never a keeper. RESULT (scored P2 pass): CT_PEAKER 0.83/0.55/0.39 TWh (drag-ON caiso-55: 2.12/1.73/1.30; measured 3.08/3.30/1.65) \u2014 the ablation delta 1.29/1.18/0.91 TWh matches the caiso-55 D-2 drag attribution (1.26/1.15/0.90) within ~2%, a clean D-3 validation of the D-2 accounting: the drag's net class contribution equals its gross binding-floor energy. Without the drag the class collapses to ~25% of actual (the pure evening merit tail \u2014 CT clears only where LMP >= its cheapest band, FINDING-caiso-evening-merit). D-2 PASSES (CT forced 0.8/1.4/0.03%, sole remaining mechanism ra_mustoffer_bridge; CC_REGULAR 5.3/4.8%); D-1 CT r 0.783/0.734/0.707, CV ratio 3.1-3.5 (both arms fail D-1, small noisy fleet). C3a +21.4/+36.3/+43.7% (~caiso-52 level: the drag barely moves mean LMP); 2023 >$200 tail 479 h vs 21 actual (the floor was suppressing artificial evening scarcity the model now prices; C3c honest-fail). Disposition per docs/handoffs/caiso-ct-drag-d8-closure-2026-07.md: the drag stays (most structurally faithful available mechanism, rule 1) until the ramp/LCR build (docs/ramp-locational-design-2026-07.md) takes the load off it; D-8 LOYO instability remains open (G-15). NEVER a keeper candidate.", "file": "frontend/data/backcast/runs/2026-07-06-caiso-56-zero-drag.js", "id": "2026-07-06-caiso-56-zero-drag", "iso": "CAISO", "label": "caiso 56 zero drag", "shorthand": "caiso-56-zero-drag", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "PROBE \u2014 D-8 closure A/B arm Y (G-15; keeper stays caiso-51, NEVER a keeper). Byte-faithful replay of the caiso-51 keeper config at HEAD, deltas exactly the closure plan's arm (docs/handoffs/caiso-ct-drag-d8-closure-2026-07.md \u00a74): ct_netload_drag OFF + ramp_limits ON + local_capacity_constraints ON; use_plant_emission_rates_v2 OFF exactly as the keeper ran (clean A/B vs caiso-55 drag arm / caiso-56 zero-drag; shared-input hashes byte-identical across the chain). VERDICT: decision-rule FAIL on criterion (i) in all three years -> the drag STAYS, G-15 stays open. Scored (P2) evening h15-21 CT 309/146/106 MW vs drag arm ~690-860/~580-600/~425-445 (CAMPD actual 850/770/303); CT class 1.73/0.73/0.68 TWh vs drag 2.04/1.70/1.30, actual 3.05/3.30/1.65. Criteria (ii)/(iii) hold: D-4 off-window 0%, D-2 CT forced share 0.4/1.0/0.03% (LCR attributes NO CT forcing - its dual is uplift-like by design), 2023 CT D-1 r 0.803/CV 0.883 best-in-chain; mean SP15 LMP unchanged vs the drag arm (69.2/46.5/48.7 - neither drag nor ramp+LCR moves C3a). vs caiso-56 (no mechanisms) the pair adds +0.93/+0.18/+0.29 TWh CT - the HEAD LCR contribution is far larger than the 07-04 unregistered probe measured (2023 LA-Basin requirement + scarcity hours). NEW ROOT CAUSE (sharpest of the session): the P1->P2 gap (P1 evening CT 552/236/127) shows the P2 UC decommit strips locally-committed CT because the commitment hurdle credits no LCR shadow value / bid-cost recovery - reality's CAISO pays exactly that uplift; the evening-CT suppressor has MOVED from the P1 merit order into P2 commitment economics. That build (LCR-dual credit in the P2 margin) is the fail branch's follow-up, never a re-tuned drag (rules 1/19).", "file": "frontend/data/backcast/runs/2026-07-06-caiso-57-ramp-lcr.js", "id": "2026-07-06-caiso-57-ramp-lcr", "iso": "CAISO", "label": "caiso 57 ramp lcr", "shorthand": "caiso-57-ramp-lcr", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-06-caiso58-v2-regate-ablation", "date": "2026-07-06", "definition": "KEEPER (G-11 owner decision 2026-07-06: caiso-58 promoted to baseline, replacing caiso-51 which no longer reproduces at HEAD after PR #1279 CT-floor scrub). The caiso-51 keeper config replayed byte-faithfully at HEAD with use_plant_emission_rates_v2=true (G-39 owner decision \u2014 v2 is the default going forward). Drag ON per D-8 closure fail branch (caiso-57 A/B FAILED criterion i). CT 2.05/1.70/1.36 vs measured 3.05/3.30/1.65 TWh; D-2 CT forced share 59.7/65.9/65.4% (honest rule-20 disclosure \u2014 the ct_netload_drag is a structural reliability-commitment mechanism; C8 forced-energy budget is NOT a legitimate blocker per owner decision, rule 1); D-4 off-window 0% all years. The next build target is the P2 LCR-dual-credit proxy (D-8 closure \u00a76, G-15) to replace the drag with a real market mechanism.", "file": "frontend/data/backcast/runs/2026-07-06-caiso-58-v2-regate.js", "id": "2026-07-06-caiso-58-v2-regate", "iso": "CAISO", "label": "caiso 58 v2 regate", "shorthand": "caiso-58-v2-regate", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "PROBE (G-15 option C): LCR commitment credit proxy ON, ct_netload_drag OFF, local_capacity_constraints ON. Tests whether the P2 LCR-dual credit (CAISO BCR/CPM analogue, Tariff \u00a740.6) replaces the drag as a commitment-value mechanism. CT 1.39/0.40/0.78 vs measured 3.05/3.30/1.65 TWh; avg price $68.05/$44.99/$51.04 vs actual ~$66/$45/$55. The proxy alone does NOT replace the drag's CT-holding effect \u2014 CT drops ~0.6\u20131.3 TWh/yr vs caiso-58 keeper \u2014 but it is structurally correct (real market mechanism). The remaining CT gap requires a complementary mechanism (D-8 closure \u00a76: the drag carried both commitment-value AND scarcity-pricing roles).", "file": "frontend/data/backcast/runs/2026-07-06-caiso-59-lcr-proxy.js", "id": "2026-07-06-caiso-59-lcr-proxy", "iso": "CAISO", "label": "caiso 59 lcr proxy", "shorthand": "caiso-59-lcr-proxy", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "(PROBE, issue #1492 / L-10) caiso-51 + the new CAISO per-generator energy+reserve co-optimization (_caiso_design): BAL-002-WECC-3 contingency requirement (max(MSSC, 6% load), half spin/half non-spin) priced by the published tariff \u00a727.1.2.3.5 scarcity demand curves (spin 10% flat / non-spin 50/60/70% at 70/210 MW), Spin+Non-Spin co-drawn on one ramp10-bounded pergen pool. RESULT: real but LARGELY INERT (the MISO lesson) \u2014 the ~12.9 GW ramp-deliverable pool dwarfs the ~2.2 GW requirement, so it fires in only 100 hours of 2023 (reserve price up to $800 = spin $100 + non-spin $700, confirming the co-opt sums the product duals) and is idle in 2024/2025. Effect vs the caiso59_reserve_ab_base twin: C3a mean LMP +$0.47 in 2023 only (+0.0 in 2024/2025); C3c DA-expressible >$200 tail UNCHANGED (2023 483h model vs 41h DA / 21h RT actual; +16 zone-hours, 0 net system-hours). Answers the ~455h-vs-21h driver question NEGATIVE: the 2023 over-tail is NOT a missing-reserve-scarcity gap \u2014 adding the published reserve co-opt leaves it at 483h; it is owned by the evening-merit / RA-commitment-uplift gap (FINDING-caiso-evening-merit-2026-07-04). Structural mechanism kept per rule 1 (default-off caiso_reserve_coopt). Storage/hydro/regulation are documented next increments. Determination NOT-YET (governance UNATTESTED \u2014 probe).", "file": "frontend/data/backcast/runs/2026-07-06-caiso-59-reserve-coopt.js", "id": "2026-07-06-caiso-59-reserve-coopt", "iso": "CAISO", "label": "caiso 59 reserve coopt", "shorthand": "caiso-59-reserve-coopt", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-06-caiso-60-p1-native-ablation", "date": "2026-07-06", "definition": "P1-native RA must-offer bridge (P2 archived). The caiso-58 keeper config re-solved P1-only: P2 is archived (P0/P1 are the only production passes, every run scored on P1), and the CAISO RA must-offer bridge \u2014 which used to ride the P2 pass \u2014 is now a P1-native min_gen floor detected from the base-cost P0 run pattern and applied before the single P1 clearing solve. Same verdict profile as caiso-58 (no calibration regression); the ra_mustoffer bridge forces ~6% of CC_REGULAR energy (well within the 30% budget).", "file": "frontend/data/backcast/runs/2026-07-06-caiso-60-p1-native.js", "id": "2026-07-06-caiso-60-p1-native", "iso": "CAISO", "label": "caiso 60 p1 native", "market_story": "ra_mustoffer_bridge on CC_REGULAR (~3.4-3.9 TWh/yr, ~6% of class): CAISO's Resource-Adequacy must-offer obligation keeps the merchant gas CC fleet committed through the midday solar belly \u2014 a unit that runs before and after a midday idle gap shorter than its min-down cannot economically cycle off and restart for the evening ramp, so it is held at min-load rather than cold. This reproduces real CAISO, where several GW of RA gas stays committed at min-load through the deep spring belly; the LP, paying no startup on a continuous ramp, would otherwise over-cycle it. The floor only binds when oversupply would drive a committed unit cold; the midday ~$0 price comes from real solar/import oversupply, not the floor.", "shorthand": "caiso-60-p1-native", "years": [2023, 2024, 2025]}, {"ablation_of": "2026-07-06-caiso-60-p1-native", "date": "2026-07-06", "definition": "ABLATION TWIN of 2026-07-06-caiso-60-p1-native \u2014 zero-forcing reference solve (every merchant floor/bridge OFF, keeping only nuclear must-run, CHP steam-following, coal take-or-pay). The keeper-vs-twin per-class delta shows what the RA must-offer bridge (and the CT net-load drag) buys. Same config as the keeper, P1-only.", "file": "frontend/data/backcast/runs/2026-07-06-caiso-60-p1-native-ablation.js", "id": "2026-07-06-caiso-60-p1-native-ablation", "iso": "CAISO", "label": "caiso 60 p1 native (ABLATION TWIN)", "shorthand": "caiso-60-p1-native-ablation", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "STALE vs current CAISO keeper 2026-07-06-caiso-58-v2-regate (bundle caiso58_v2_regate) \u2014 despite the \"v2\" label this probe still replays the superseded caiso51_firm_base (caiso-51-firm-base) keeper (the \"v2\" refers to a code/basis delta, not a keeper re-gate); it is not a same-SHA replay of the current keeper (G-10 gap register: 'CAISO/NYISO r2 confounded with offer-curve merges, no same-SHA keeper replay'). A fresh replay against caiso58_v2_regate is queued, not done here. Original definition: D-7 statistical-mode A/B probe: byte-faithful replay of keeper caiso51_firm_base (meta.json) with every per-hour/per-year answer-injection overlay off (outage_source=statistical, ct_deployment_overlay=False, reliability_deployment_overlay=False, wefor_residual/groups=None, coal_plant_monthly_pricing=False). Structural model + realized annual Henry Hub gas price unchanged. Probe only \u2014 not a keeper, per CLAUDE.md #1/#13.", "file": "frontend/data/backcast/runs/2026-07-06-caiso51-statmode-v2.js", "id": "2026-07-06-caiso51-statmode-v2", "iso": "CAISO", "label": "caiso51 statmode v2", "shorthand": "caiso51-statmode-v2", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "(ABLATION TWIN of 2026-07-06-caiso-58-v2-regate) D-3 zero-forcing twin (CLAUDE.md rule 20): the caiso-58 keeper recipe verbatim with all merchant floors/bridges zero-forced (protected set only: nuclear must-run, CHP steam-following, coal take-or-pay), including the ct_netload_drag. The keeper-vs-twin per-class delta shows what each remaining floor buys. Registered to satisfy audit E9 / rule 20 for the CAISO keeper (gap G-01).", "file": "frontend/data/backcast/runs/2026-07-06-caiso58-v2-regate-ablation.js", "id": "2026-07-06-caiso58-v2-regate-ablation", "iso": "CAISO", "label": "caiso 58 v2 regate (ABLATION TWIN)", "shorthand": "caiso58-v2-regate-ablation", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-06-ercot34-stage4-overlay-off-ablation", "date": "2026-07-06", "definition": "ercot34 stage-4 overlay-off integration (AS co-opt plan \u00a76/\u00a77, G-38; KEEPER-CANDIDATE recommendation, owner sign-off pending): the ercot32 keeper recipe (incl. the four gas-geography fields meta.json does not persist, restored via --set \u2014 see run_config.json) with exactly two deltas: ercot_dam_as_overlay=False (the measured DAM-AS overlay retired \u2014 the plan's replacement-under-test) + ercot_reserve_supply_forward=True (WS-A forward RTOLCAP/RTOFFCAP formula supply). WS-B endogenous storage swap NOT taken (stage-2 gate 0.54-0.61x vs 0.8-1.3x band; plan \u00a74 conditions the swap on validation) \u2014 measured storage treatment retained. P1-only. GATES (vs same-code ex-overlay baseline ercot36 + RT actuals): G-3 PASS decisively (max monthly \u0394 = $0.00 \u2014 no ercot27 broad-elevation artifact; Feb-2023 unchanged); G-5 PASS (WS-A coverage 2.02/2.08/2.21x ~2x, one-delta \u0394ann \u2264 $0.05, tails 92-vs-93/22/7; WS-B deferred, documented); G-6 PASS (RTORDPA\u2227adder \u03a3min $543/$104/$2, 46/11/0 joint h, \u22648.3% of the smaller channel); G-2 2025 MAE +0.65 \u2264 +$1 and Aug-2024 -1.11 within \u00b1$3 PASS, Aug/Sep-2023 +12.3/+11.8 vs committed keeper EXCEEDS \u00b1$3 \u2014 100% HEAD base-code movement (same-code \u0394 -0.09/-0.40), toward actual; G-1 May-2024 acute days on RT -56/+34/-51% FAIL \u00b125% \u2014 named: F6 DA-boundary (overlay carried Jan/May -14.3/-20.5 non-reproducible dw) + the G-22 online-capability wedge; G-4 2023 tail 92h 0.51x (keeper 0.43x), >$500 83 vs 68 not collapsed, 2024 honest 22h \u2261 same-code ex-overlay (keeper's 78 was 72% overlay-carried), 2025 7 vs 10 (removed overlay hours). G-22 fold: in the 106 missed 2023 tail hours the co-opt adder is ~0 (p50 $0.1, >$10 in 1h) with measured RTOLCAP 8.1 GW above the knee \u2014 endogenous reserve withholding closes NONE of the shape miss; the miss stays offer/commitment-carried per the FINDING. C-scores vs keeper: C1 flips to PASS, C3a-2024 passes on RT ex-overlay, C3b-2023 0.393->0.324, C3c honest 0.51/0.42/0.23x all FAIL (2024's prior pass was overlay-carried). Plan \u00a76 keeper rule satisfied (G-3/G-5/G-6 pass; every G-1/G-2/G-4 miss carries a named G-7 root cause). PROMOTED TO KEEPER 2026-07-06 (owner sign-off in-session): C6 attestation + DOF ledger (12 entries, WS-A identified on measured RTOLCAP quantities) in the bundle; zero-forcing ablation twin registered and linked. REPLAY NOTE: meta.json does not persist the five --set fields \u2014 restore from run_config.json on any replay (G-12).", "file": "frontend/data/backcast/runs/2026-07-06-ercot34-stage4-overlay-off.js", "id": "2026-07-06-ercot34-stage4-overlay-off", "iso": "ERCOT", "label": "ercot34 stage4 overlay off", "market_story": "CT_PEAKER: the evening reliability floor (window h15-21, net-load-ramp driver) stands in for the day-ahead/RUC reliability commitments ERCOT actually holds online through the evening ramp \u2014 0.73 TWh forced in 2023 (12.4% of class, the disclosed C8 fail; 0.07/0.06 TWh in 2024/25). ST_GAS/ST_CHP: wefor_residual=0.06 availability relief stands in for the heat/drought steam-unit derate slack the >=2-day CAMPD outage detector cannot see (audit C-15 open item \u2014 a real physical phenomenon, imperfectly proxied). The twin also resets wefor_multiplier to 1.0, so per-class deltas are net of the wind-availability channel: keeper-vs-twin CT_PEAKER -1.0/-1.4/-1.9, ST_GAS +1.2/+1.4/+1.2, CC_REGULAR -0.9/-0.7/-0.8 TWh (2023/24/25) \u2014 the CC/coal movement is merit-order re-equilibration, not floor-bought energy.", "shorthand": "ercot34-stage4-overlay-off", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "(ABLATION TWIN of 2026-07-06-ercot34-stage4-overlay-off; CLAUDE.md rule 20/21 D-3/E9.) The exact ercot34 keeper config (overlay off + WS-A forward supply + the four restored gas-geography fields, all re-applied via --set because meta.json does not persist them) solved through ScenarioConfig.as_zero_forcing_ablation: every merchant floor/bridge OFF (reliability_floor false; wefor_multiplier 1.0, wefor_residual removed), keeping only nuclear must-run, CHP steam-following and coal take-or-pay. The keeper-vs-twin per-class delta shows what each floor buys; see the keeper sidecar's market_story.", "file": "frontend/data/backcast/runs/2026-07-06-ercot34-stage4-overlay-off-ablation.js", "id": "2026-07-06-ercot34-stage4-overlay-off-ablation", "iso": "ERCOT", "label": "ercot34 stage4 overlay off (ABLATION TWIN)", "shorthand": "ercot34-stage4-overlay-off-ablation", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "ercot35 replay-metagap arm (PROBE, G-12 attribution A/B): the ercot34 stage-4 recipe (ercot32 keeper meta + ercot_dam_as_overlay=False + ercot_reserve_supply_forward=True) solved WITHOUT the four ERCOT gas-geography fields the keeper ran with but meta.json does not persist (ercot_zonal_gas_basis, ercot_west_netload_gas_shape, ercot_west_gas_delivered_floor=0.4, oil_primary_bin_fuel) \u2014 i.e. the exact config every prior 'byte-faithful' replay actually solved (32-head-regate, ercot33 baselines, ercot40 WS-A). Reproduces the head-regate's drifted class volumes EXACTLY (CC_REGULAR 145.38/153.47/145.49 TWh) on HEAD in a fresh container, proving the G-12 'reproducibility drift' is a deterministic replay-contract gap, not solve noise. vs ercot34 (same code, flags restored) isolates the M1 mover: CC_REGULAR +6.3/+10.8/+3.7 TWh, West-Texas CT collapse, coal (PRB+lignite) -5.7/-10.2/-1.3. D-2 CT_PEAKER 15.9% FAIL under the drifted config (keeper's floors starved of CT volume). NOT a keeper candidate; attribution evidence: docs/FINDING-ercot-priceshape-2026-07.md \u00a76.3 addendum.", "file": "frontend/data/backcast/runs/2026-07-06-ercot35-replay-metagap-arm.js", "id": "2026-07-06-ercot35-replay-metagap-arm", "iso": "ERCOT", "label": "ercot35 replay metagap arm", "shorthand": "ercot35-replay-metagap-arm", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "ercot36 head config-faithful keeper replay (PROBE, G-12 closure + stage-4 same-code baseline): the ercot32 keeper meta replayed on HEAD 3b31193 with the four un-persisted gas-geography fields restored via --set (ercot_zonal_gas_basis, ercot_west_netload_gas_shape, ercot_west_gas_delivered_floor=0.4, oil_primary_bin_fuel \u2014 from the keeper's resolved run_config.json), DAM-AS overlay ON (keeper state). Result: the committed keeper does NOT reproduce on HEAD even config-faithfully \u2014 CC_REGULAR 139.07/142.68/141.81 vs committed 133.21/135.64/135.31 TWh \u2014 and the residual is exactly the two legitimate merged re-derives: the coal max-CF ceiling re-derive (f5543232, year-pins dropped: COAL_PRB +3.9/+3.9/+3.8) and the fleet.py curated-bin-drift CHP relabelling (CC_CHP -3.8/-3.9/-4.0, mostly label movement). Note the HEAD volumes land CLOSER to CAMPD-measured (2023 CC_REGULAR actual 141.7). Also the same-code overlay-on baseline the ercot34 stage-4 gates difference against: its overlay-on-vs-off pair reproduces the WS-F decomposition arithmetic exactly (2024 overlay dw +4.51, 56 overlay-carried tail hours). Not a keeper candidate; evidence: FINDING-ercot-priceshape \u00a76.3 addendum, calibration-log 2026-07-06.", "file": "frontend/data/backcast/runs/2026-07-06-ercot36-head-config-faithful.js", "id": "2026-07-06-ercot36-head-config-faithful", "iso": "ERCOT", "label": "ercot36 head config faithful", "shorthand": "ercot36-head-config-faithful", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "(PROBE) Control / same-code attribution twin for the G-22 CT offer-surface A/B (paired with 2026-07-06-ercot37-g22-surface-on): ercot34 recipe with the 5 un-persisted fields restored from run_config, surface OFF. Reproduces ercot34; near-actual LMP bias (2024 -0.9, 2025 +2.0, 2023 -6.5). The -on twin over-corrects, so the keeper stays ercot34 and the surface stays default-off.", "file": "frontend/data/backcast/runs/2026-07-06-ercot37-g22-surface-off.js", "id": "2026-07-06-ercot37-g22-surface-off", "iso": "ERCOT", "label": "ercot37 g22 surface off", "shorthand": "ercot37-g22-surface-off", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "(PROBE \u2014 REJECTED) G-22 condition-responsive CT/peaker offer surface ON: raises CT econ+peak tranche bids to the measured 60-Day-DAM self-withholding level (~$1,500 cap band) above the 90th net-load percentile. A/B vs the -off twin over-corrects the LMP level in every year, including the current-design years it must not hurt: 2024 bias -0.9->+3.0 (monthly MAE 2.3->4.6), 2025 +2.0->+8.4 (MAE 2.2->8.4), 2023 -6.5->+15.6. Tails move the right direction (2024 >$200 22->42 vs actual 53) but the flat p50 post collapses the fleet's measured heterogeneity (p25 still $150 above the hinge) and removes ~3.2 GW spare in one step. Confirms the wedge is not purely offer-height: needs commitment-thinness / heterogeneity-preserving surface (filed). Keeper stays ercot34; mechanism stays default-off (rules 1/11/26).", "file": "frontend/data/backcast/runs/2026-07-06-ercot37-g22-surface-on.js", "id": "2026-07-06-ercot37-g22-surface-on", "iso": "ERCOT", "label": "ercot37 g22 surface on", "shorthand": "ercot37-g22-surface-on", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "ercot38: one-delta probe of ercot34 (stage-4 overlay-off keeper) -- measured ERCOT NP4-732/737 HSL now intaken for 2024/2025 (previously G7 reference-curtailment-rate gross-up fallback). Same recipe as ercot34 (five gas-geography/WS-A prb_overrides restored via --set since meta.json only nests them under coal_prb_sigmoid_overrides); the only delta is renewables.hsl_potential_mw now resolving real 2024/25 HSL parquets instead of the fallback. RESULT (vs ercot34, both NOT-YET): C3a mean LMP CAVEAT->PASS (2025 commercial-band miss +8.2% resolved) and C5c storage shape CAVEAT->PASS (2024 r=0.422 accepted-limitation resolved); C2 system volume CAVEAT->FAIL (2025 gas -5.0%->-6.4%, crossing out of the commercial band -- measured HSL dispatches slightly more wind/solar, displacing gas). C3b/C3c price-shape/tail stay FAIL unchanged (pre-existing structural misses, untouched by this delta). Governance shows UNATTESTED because this probe carries no calibration_attestation.json/DOF ledger/ablation twin (keeper-only requirement, rule 21) -- not a regression. Net: mixed, modest movement; not a wholesale improvement or regression. NOT a keeper swap -- registered as an informational probe pending owner review of whether to promote (PROBE).", "file": "frontend/data/backcast/runs/2026-07-06-ercot38-measured-hsl-2425.js", "id": "2026-07-06-ercot38-measured-hsl-2425", "iso": "ERCOT", "label": "ercot38 measured hsl 2425", "shorthand": "ercot38-measured-hsl-2425", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "(PROBE) one-delta probe of ercot38 with ercot_gtc_limits_measured active (curated NP6-86 GTC series replacing static TTC on the Panhandle/West/Northeast export links). NEGATIVE RESULT: did NOT close the wind/solar under-curtailment gap \u2014 model curtailment stayed ~2-3% vs ISO-reported 5-9% and in 2024/25 moved slightly AWAY (the measured export caps are frequently looser than the static fill, e.g. 2024 PNHNDL 2065-3544 MW vs 2680 static, WESTEX 6571-7902 vs 7300). C-score matrix identical to ercot38: C2 gas volume still FAIL (2025 gas -6.5% vs ercot38 -6.4%), C3a/C5c still PASS (no regression). Transmission congestion is not the binding under-curtailment mechanism; next candidates per docs/handoffs/ercot-vre-undercurtailment-2026-07.md \u00a75.2 (neg-price dumping, storage absorption timing). Not a keeper (no attestation).", "file": "frontend/data/backcast/runs/2026-07-06-ercot39-gtc-measured.js", "id": "2026-07-06-ercot39-gtc-measured", "iso": "ERCOT", "label": "ercot39 gtc measured", "shorthand": "ercot39-gtc-measured", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "G-22 online-capacity envelope A/B: CONTROL arm = ercot34 recipe (overlay-off + WS-A forward supply + 4 gas-geography flags), envelope OFF. Solved fresh on HEAD for apples-to-apples with the treatment arm. PROBE.", "file": "frontend/data/backcast/runs/2026-07-06-ercot41-envelope-off.js", "id": "2026-07-06-ercot41-envelope-off", "iso": "ERCOT", "label": "ercot41 envelope off", "shorthand": "ercot41-envelope-off", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "(ABLATION TWIN of 2026-07-05-miso-41-ct-evening) D-3 zero-forcing ablation twin of the miso-41-ct-evening keeper (CLAUDE.md rule 20): the miso-41 recipe (de-leaked default offer curve + CT_PEAKER evening-window reliability floor) verbatim, same 2023-2025 span, with every merchant floor/bridge neutralized via ScenarioConfig.as_zero_forcing_ablation (off-list from the D-2 mechanism registry), structural protected set kept (nuclear must-run, CHP steam-following, coal take-or-pay). Keeper-vs-twin per-class delta (real solved dispatch, not the D-2 fleet_only reconstruction): CT_PEAKER +3.2/+3.8/+4.7% (2023/24/25) \u2014 confirms the miso-41 evening-window floor is immaterial once fully removed, matching its own tiny 0.02-0.08 TWh/yr forced share; ST_GAS +115/+95/+63% \u2014 no longer crowded out once other floors stop consuming load; OTHER_FOSSIL -100% all years (4.0/3.7/2.5 TWh/yr to zero) \u2014 entirely floor-forced, an open root-cause item (rules #1/#11: which mechanism carries it is not yet isolated); coal subtypes -0.7% to -1.2%, CC_REGULAR/CC_CHP within \u00b10.4%. Registered alongside the keeper for the E9 keeper-vs-twin delta; not a keeper candidate.", "file": "frontend/data/backcast/runs/2026-07-06-miso-41-ct-evening-ablation.js", "id": "2026-07-06-miso-41-ct-evening-ablation", "iso": "MISO", "label": "miso 41 ct evening (ABLATION TWIN)", "shorthand": "miso-41-ct-evening-ablation", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "(PROBE \u2014 NOT a keeper swap; no LP solve) v2 emission-rate re-score of keeper miso-41-ct-evening under use_plant_emission_rates_v2=True. Dispatch/prices/generation are PROVABLY byte-identical (emission_rate enters mc only via emission_rate\u00d7carbon_price; MISO has no state carbon program and backcast carbon_price=0 \u2014 the committed runs.js carries a COMPACT CO2/fuelmix registration payload \u2014 the per-plant panels are omitted (data identical to the keeper's), and the full payload was verified byte-identical to the keeper before compaction). Only CO2 accounting moves. Re-scoring the keeper's persisted per-plant model generation (committed dashboard payload m_ann) through the v2 target-year rate map: COVERAGE 90.2/91.1/93.5% of model fossil GWh now carries a MEASURED plant-specific CO2 rate \u2014 MISO's FIRST measured rates (pre-v2 every MISO plant booked the generic heat_rate\u00d7FUEL_CO2 default; the legacy artifact is TX-only). v2-basis model CO2 235.6/231.8/269.1 Mt over covered generation (2023/24/25); on the matched plant subset the v2 basis is \u22120.53/\u22122.65/\u22123.30% vs the eGRID+CAMPD-v1 basis \u2014 small, no distortion (the larger raw-total gap is the ~7-10% not-yet-CEMS-covered generation, not a rate error). Dashboard C5a verdict UNCHANGED (reads egrid.fossil_co2_rate_map, not v2). Rules #1/#13/#15/#22: no retune, no keeper swap, holdouts untouched (only 2023-2025 read). \u00a79.6 lane L-8b.", "file": "frontend/data/backcast/runs/2026-07-06-miso-41-v2rescore-probe.js", "id": "2026-07-06-miso-41-v2rescore-probe", "iso": "MISO", "label": "miso 41 v2rescore probe", "shorthand": "miso-41-v2rescore-probe", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-06-miso-42-coal-econ-ablation", "date": "2026-07-06", "definition": "MISO 42 (CANDIDATE, L-14 G-23 lever; keeper stays miso-41 pending owner call): miso-41 recipe + coal_econ_srmc_bound \u2014 the marginal (econ*/peak) coal tranches' fuel passthrough is clamped to >=1.0 so no marginal coal offer sits below the plant's measured F923 incremental delivered SRMC; the committed/must-run bands keep the contracted take-or-pay discount. Removes the passthrough sigmoid's fitted discount from tranches whose fuel is bought at market (FINDING-miso-burndown-2026-07.md Evidence 2: model LMP sat $4-5 below the cheapest measured coal tranche while coal was marginal ~94% of hours) \u2014 a DOF reduction, nothing tuned. RESULT vs miso-41: the priced-out classes wake up structurally (ST_GAS 2.9/3.3/3.4 -> 6.8/7.3/5.3 TWh; CT_PEAKER 13.4/17.3/16.9 -> 15.0/20.8/17.6; net imports 14.7/3.7/-5.1 -> 19.5/6.3/-4.6 vs actual 37.9/23.1/19.0); C3a improves all 3 years (-8.2/-13.0/-18.9% vs -9.8/-15.6/-19.5%); 2025 coal over-run improves (C2 +7.2% vs +8.8%); CO2 PASS x3; legitimacy D-gates Overall PASS (C7/C8 PASS, zero forced energy from the bound \u2014 it is an offer bound, not a floor). COSTS: coal 2023/24 under-run deepens (154.9/144.2 vs actual 175.0/167.1 \u2014 the sigmoid discount was silently compensating for missing coal self-commitment volume; the committed band is not yet sized from the measured EIA-923 Sch-5 contract share in the MISO fleet branch) and CC_REGULAR worsens +2.9/+4.3/+1.8 to +46.4/+46.8 TWh (2023/24) \u2014 confirming per FINDING-miso-cc-decomposition-2026-07.md that the CC row is the P1 commitment-posture wedge (DP-1: +34% committed CC energy vs MIP; 135.6x1.34=181.7~=model), designed (not built) in docs/multi-iso/miso-scarcity-posture-design-2026-07.md. C3c tail still 0 h (needs the posture lever). C5b 2025 (+1296.7%) is a benchmark basis artifact, not a model miss \u2014 EIA-930 MISO reports battery-only while the model side includes the 2,417 MW PS fleet whose throughput matches the eGRID net-energy-implied band (FINDING-miso-c5b-storage-benchmark-2026-07.md).", "file": "frontend/data/backcast/runs/2026-07-06-miso-42-coal-econ.js", "id": "2026-07-06-miso-42-coal-econ", "iso": "MISO", "label": "miso 42 coal econ", "market_story": "Zero-forcing twin deltas are SMALL under the SRMC bound (all classes within ~7%/1.9 TWh): CT_PEAKER +2.8/+3.2/+4.4% and ST_GAS +4.8/+6.9/+6.4% (floors off, these classes still run - they clear economically once marginal coal offers at its measured delivered SRMC, so the evening-reliability floor is commitment scaffolding, not their dispatch model); OTHER_FOSSIL +4.4-6.4% (contrast the miso-41 twin where it was 100% floor-forced and ST_GAS moved +63-115%: the bound, not the floors, now carries the mid-merit price floor); imports +1.9/+1.2/+0.9 TWh (floor-forced domestic energy was crowding out the priced seam); CC/coal families -0.1 to -1.4%. The real market runs these classes on price, and with the fitted coal discount removed the model does too - the floors' forced share collapses toward the C8 budget's spirit.", "shorthand": "miso-42-coal-econ", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-06-miso-42-coal-econ", "date": "2026-07-06", "definition": "(ABLATION TWIN of 2026-07-06-miso-42-coal-econ, PROMOTED to the MISO keeper 2026-07-06) D-3 zero-forcing ablation twin of the miso-42-coal-econ candidate keeper (CLAUDE.md rule 20): the miso-42 recipe verbatim (coal_econ_srmc_bound KEPT - it is an offer bound, not a floor), same 2023-2025 span, with every merchant floor/bridge neutralized via ScenarioConfig.as_zero_forcing_ablation (off-list from the D-2 mechanism registry), structural protected set kept (nuclear must-run, CHP steam-following, coal take-or-pay). Re-solved from scratch on HEAD ac11191 in the L-14 continuation session after the Wave-3 container died mid-twin (PR #1486 checkpoint); all MISO-affecting src is unchanged between the base run's sha 632e10d and ac11191 (NYISO/NEISO-gated or dead-constant deletions only), and the EIA-930 MISO extract backfill (a2cb5c2) added 2019-2021 rows only - the 2023-2025 slices the solve reads are unchanged. UNUSUAL DASHBOARD ROLE (updated 2026-07-06): this sidecar was originally registered purely as the E9 keeper-vs-twin diagnostic and was NOT itself a new mechanism or a keeper candidate - but keepers.json now designates THIS zero-forcing twin, rather than the base recipe, as the MISO keeper, superseding 2026-07-05-miso-41-ct-evening; the base recipe 2026-07-06-miso-42-coal-econ (bundle miso_42_coal_econ_srmc) remains separately registered as the un-ablated candidate this twin was solved to validate, and was the run actually recommended for promotion in the 2026-07-06 calibration log. Because the twin and base share the coal_econ_srmc_bound offer bound and differ only in the zero-forced merchant floors/bridges, the determination is unchanged from the base recipe: NOT-YET (current live verdict; governance gate UNATTESTED for this bundle). Per the keeper-promotion commit's own note (rule 21): because this keeper is itself the zero-forcing run, its E9 ablation-twin slot is inverted from the usual pairing - it is the forced-floors main run, 2026-07-06-miso-42-coal-econ, whose sidecar's market_story field already carries the keeper-vs-twin per-class delta this field exists to surface. Remaining provenance gap, not a text-accuracy issue: this bundle carries no calibration_attestation.json/DOF ledger of its own (audit E8) - the DOF ledger committed to date covers the base run's bundle (miso_42_coal_econ_srmc), not this ablation-twin bundle (miso_42_coal_econ_srmc-ablation) that now serves as keeper - flagged for the owner, not silently fixed here.", "file": "frontend/data/backcast/runs/2026-07-06-miso-42-coal-econ-ablation.js", "id": "2026-07-06-miso-42-coal-econ-ablation", "iso": "MISO", "label": "miso 42 coal econ (ABLATION TWIN, now MISO KEEPER)", "shorthand": "miso-42-coal-econ-ablation", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "(PROBE - honesty gate FAIL, lever stays default-off) miso-43: the miso-42 recipe + miso_commitment_posture, the design-note SA pooled linear commitment-posture lever (G-25/DP-1) built this session: per non-fast-start (zone x class) pergen pool an online-capacity variable U with joint P+R<=U, CEMS-measured min-load coupling P>=mlf*U (thermal_tranches committed_pct, WWSIS-2 gap-fill), an NREL-class startup charge on dU+ (18 of 30 pools postured by the rule-18 physics gate; mlf 0.12-0.58, startup $44-100/MW), and the pergen reserve cap online-gated R<=rho(t)U. Zero fitted parameters. HONESTY GATE (SUMMARY-posture-gate.md, vs the measured MISO ASM series intaken this session, data/raw/MISO-AS): FAIL on level - modeled postured online headroom 9.9-11.1 GW vs measured cleared reserve 2.5-2.7 GW (3.7-4.2x too loose); direction only partial (daily r model-reserve-price vs spin MCP 0.00/0.20/0.31; top-20 event days same-direction 19/19/15 of 20); regional split over-weights South (34-38% vs measured 13-18%). Structural effects, verified not tuned: reserve duals fire 637/700/470 h/yr (vs 59/64/207 in miso-39) and startups now cost 102/107/139 GW*$/MW-yr of real cycling charge, but the $200 curve step still never engages (C3c tail 0 h x3) and the C1 CC row is UNCHANGED (+0.8/+0.5/+0.3 TWh vs miso-42; imports -2.1/-1.2/-0.9 TWh, slightly worse) - the LINEAR pool relaxation holds ~10 GW online at min-load ($2.19-3.52 gas makes min-load burn cheaper than the curve), capturing only a small part of the DP-1 MIP wedge. Named follow-ups: min-run/min-down rolling-window rows on U (deferred, G-40 memory-gated), the Midwest zonal family (B, still DATA-BLOCKED on the historical zonal requirement series), and a tighter posture grain. Keeper unchanged.", "file": "frontend/data/backcast/runs/2026-07-06-miso-43-commitment-posture.js", "id": "2026-07-06-miso-43-commitment-posture", "iso": "MISO", "label": "miso 43 commitment posture", "shorthand": "miso-43-commitment-posture", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "miso-44 ablation twin: zero-forcing of miso-44 (wefor already at 1.0; floors off)", "file": "frontend/data/backcast/runs/2026-07-06-miso-44-ablation.js", "id": "2026-07-06-miso-44-ablation", "iso": "MISO", "label": "miso 44 ablation", "shorthand": "miso-44-ablation", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-06-miso-44-ablation", "date": "2026-07-06", "definition": "miso-44: miso-42 recipe + wefor_multiplier neutralized 0.7\u21921.0 (DOF reduction, audit C-15). Root-cause: the miso-42 ablation twin scored better because wefor=0.7 was silently subsidizing CC availability (lowering thermal EFOR 30%), not because the reliability floors were harmful. Neutralizing wefor halves the CC over-run (+44\u2192+20 TWh) and improves prices (C3a from -15.6\u2192PASS in 2024). Reliability floors KEPT (all structurally sound, <0.6 TWh total forced). 6 residual-identified DOFs (vs miso-42's 7).", "file": "frontend/data/backcast/runs/2026-07-06-miso-44-wefor-neutral.js", "id": "2026-07-06-miso-44-wefor-neutral", "iso": "MISO", "label": "miso 44 wefor neutral", "market_story": "DOF reduction from miso-42: wefor_multiplier removed (0.7\u21921.0). The 0.7 haircut had no measured physical basis (audit C-15: scales THERMAL EFOR, not wind); root-cause of the miso-42 ablation-twin advantage was the twin's wefor neutralization, not its floor removal. With physical EFOR restored: CC_REGULAR drops from +44/+43 to +20/+19 TWh (2023/24), CT_PEAKER recovers to PASS, C3a price-mean 2024 recovers to PASS, C3b price-shape 2025 recovers to PASS. Coal 2025 over-run worsens (+8.8%\u2192+14.7%) as reduced CC availability shifts marginal load to coal \u2014 a known commitment-posture artifact. All reliability floor limbs retained (MISO-Indiana CT_PEAKER evening [15,21), MISO-Indiana COAL tmax, MISO-Plains ST_GAS tmax, MISO-South COAL tmax); forced energy <0.4% of any class (D-2 PASS). Legitimacy diagnostics Overall PASS.", "shorthand": "miso-44-wefor-neutral", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "(ABLATION TWIN of 2026-07-06-neiso-50-head-repro) D-3 zero-forcing twin: identical keeper recipe, full 2023-2025 span, every merchant floor/bridge neutralized (nuclear must-run, CHP steam-following and coal take-or-pay retained). Clears the keeper's audit_keepers E9 owner-deferred exception. Keeper-vs-twin per-class deltas are small (max +-0.17 TWh: COAL_BIT -0.17/2025, CC_CHP -0.13/2025, CT_PEAKER +0.17/2025) - the keeper is not floor-dependent. NOTE: solved at 2026-07-06 main HEAD (46fb645 + measured seam-ladder recal), which post-dates the keeper's solve commit (dd85d5a); price-level differences vs the keeper's registered numbers are dominated by main drift (see neiso52 HEAD baseline), not by floor removal.", "file": "frontend/data/backcast/runs/2026-07-06-neiso-50-ablation.js", "id": "2026-07-06-neiso-50-ablation", "iso": "NEISO", "label": "neiso 50 ablation", "shorthand": "neiso-50-ablation", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-06-neiso-50-ablation", "date": "2026-07-06", "definition": "KEEPER SWAP (promoted 2026-07-06, replacing neiso-49-stgas-netload): byte-reproducible re-solve of the IDENTICAL neiso-49 recipe (same run_config, reliability-floor CSV, offer bands, flags) on current main HEAD, not a structural change. neiso-49's registered numbers rested on an uncommitted, never-captured WIP edit at solve time (git.dirty=true) that produced a spurious NEISO zonal price separation (HQ_import pricing $0.31-$1.86/MWh below the mainland zones); a git bisection across the full commit range back to the keeper's base commit, including a clean checkout of that base, confirmed the separation never existed in any committed state and was purely a WIP artifact of that one session. neiso-49's bundle and ablation twin have been retired. The honest, reproducible price level is correspondingly worse than neiso-49's (C3a demand-weighted price: 2023 -8.3% -> -10.4%, 2024 -7.8% -> -8.6%, 2025 -1.6% -> -4.4%); C1 fuel-mix and C3b shape are unchanged to reproducibility noise. Determination stays CALIBRATED-WITH-CAVEATS (unchanged from neiso-49). D-3 UPDATE (2026-07-06): the previously owner-deferred zero-forcing ablation twin is now solved and registered (2026-07-06-neiso-50-ablation, bundle results/calibration/neiso49_resolve_confirm-ablation) and linked via this sidecar's \"ablation_twin\" field, clearing audit_keepers E9; see calibration_attestation.json exceptions (criterion: governance, RESOLVED 2026-07-06, was OWNER-DEFERRED (temporary)). Keeper-vs-twin per-class deltas are small (max +-0.17 TWh) \u2014 the fit is not floor-dependent (see market_story).", "file": "frontend/data/backcast/runs/2026-07-06-neiso-50-head-repro.js", "id": "2026-07-06-neiso-50-head-repro", "iso": "NEISO", "label": "neiso 50 head repro", "market_story": "Floors buy almost nothing in NEISO (max class delta +-0.17 TWh vs the zero-forcing twin): COAL_BIT (Merrimack) runs its take-or-pay/seasonal commitment pattern rather than pure merit (-0.17 TWh without the floor in 2025); CC_CHP/CT_CHP steam hosts hold output for industrial steam load (-0.13/-0.06 TWh); CT_PEAKER absorbs the small backfill when those floors are off (+0.17 TWh). No class's floor buys more than 0.2% of ISO load - the NEISO fit is carried by fuel/passthrough physics, not commitment scaffolding.", "shorthand": "neiso-50-head-repro", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "(PROBE) Priced interchange re-test with measured seam ladders - audit C-6 closure. IMPORT/EXPORT_TRANCHES[NEISO] rederived from measured data only (scripts/derive_neiso_import_tranches.py): per-seam Q-Q duration coupling of the measured ISO-NE DA hub LMP with measured EIA-930 per-seam flows (HQT/NBSO/NYIS), NYISO proxy-bus anchors (NYISO_HQ opportunity cost, NYISO_NPX parity), year-keyed 2023-2025 + pooled forward ladder. Keeper recipe + --priced-interchange. P9 vs the 2026-06-12 smoke (-23.5 vs -10.3 TWh, 100% import hours): net interchange now -14.8/-8.9/-9.6 TWh vs -15.1/-10.3/-8.1 actual (-2%/-13%/+18%), duration RMSE 529/609/554 MW, diurnal corr +0.46/+0.46/+0.38. C3a -6.2%/-1.2%/+2.6% vs the keeper's registered -10.4%/-8.6%/-4.4%, with REAL mechanistic HQ_import zonal separation (-$1.7 to -$3.9 vs mainland) replacing the non-reproducible WIP effect retired in the neiso-50 keeper swap. C1 12/12; C3c/C5b carry the keeper's same ledgered gaps (unattested here - probe). Attribution (see neiso52 HEAD baseline): most of the gain vs the keeper's registered numbers is main drift (use_plant_emission_rates_v2 default flip: -10.4/-8.6/-4.4 -> -6.1/-4.1/+0.5); the measured-ladder priced node itself adds -0.2/+2.9/+2.1 points on top (2024 clearly better, 2025 slight overshoot) plus the structural gains.", "file": "frontend/data/backcast/runs/2026-07-06-neiso-51-priced-ix.js", "id": "2026-07-06-neiso-51-priced-ix", "iso": "NEISO", "label": "neiso 51 priced ix", "shorthand": "neiso-51-priced-ix", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "(PROBE / re-gate baseline) HEAD re-solve of the 2026-07-06-neiso-50-head-repro keeper recipe (measured-schedule interchange, floors on) at 2026-07-06 main (46fb645 + measured seam-ladder recal, which is inert under priced_interchange=False). Isolates main drift since the keeper's solve commit dd85d5a from the neiso-51 priced-interchange ladder effect: the sole material config drift is the use_plant_emission_rates_v2 default flip (False->True, 2026-07-06), which alone moves C3a -10.4/-8.6/-4.4% -> -6.1/-4.1/+0.5% (2023/24/25). Against this baseline the neiso-51 measured-ladder priced node adds -0.2/+2.9/+2.1 points (2024 -4.1 -> -1.2 improves; 2025 +0.5 -> +2.6 overshoots slightly) plus the structural gains (real HQ_import zonal separation, forward-mechanism P9 validation). The keeper's registered numbers are stale vs HEAD; this run is the honest comparison cell for any promotion decision.", "file": "frontend/data/backcast/runs/2026-07-06-neiso-52-head-baseline.js", "id": "2026-07-06-neiso-52-head-baseline", "iso": "NEISO", "label": "neiso 52 head baseline", "shorthand": "neiso-52-head-baseline", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "(PROBE, NEGATIVE \u2014 keeper stays neiso-48) Winter-fuel Component A (oil-inventory budget) + Component B (winter fuel-security must-run: COAL/COAL_BIT/ST_GAS floored at 0.40 min-stable on Nov-Mar cold days, TMIN < -7 C NERC onset, WRP/IEP/OFSA posture) + use_plant_emission_rates_v2 (RGGI ride-along, emissions-co2-rate-plan 9.6). Single-delta A/B on neiso-48. RESULT: the winter-fuel caveats DO NOT close. COAL 0.062/0.126/0.218 TWh vs actual 0.181/0.238/0.271 (keeper 0.058/0.113/0.234) \u2014 barely moved because the ~105 MW NEISO coal fleet already runs above min-stable on cold days economically, so the commitment floor is non-binding (D-2 coal forced ~0). C3c tail unchanged 0 h >$300 all years (actual 15/8/20): Component A's inventory budget still never binds (oil 0.35/0.23/1.54 TWh unchanged \u2014 the fuel-secure fleet already burns on cold days, so B adds no incremental oil draw). C5b storage 0.91 TWh 2025 (not improved). RULE 20 PASSES: winter_fuelsec forced share ST_GAS 0.274/0/0, coal ~0 (D-2 PASS, D-4 PASS); D-1 ST_GAS shape still FAIL (pre-existing). use_plant_emission_rates_v2 is DISPATCH-INERT for NEISO \u2014 byte-identical to the v2-off twin on price/fuel/storage/CO2. Structurally faithful (rule-19 reconcile of the disabled COAL/ST_GAS tmin limbs; no residual tuning) but low-impact: REFUTES the plan hypothesis that the winter must-run is the missing mechanism behind C1/C3c/C5b. Real root cause = fleet-capacity/availability (small coal+steam fleet) + scarcity-price formation, not a missing winter commitment. Not a keeper (rule 1: kept in code default-off, not promoted).", "file": "frontend/data/backcast/runs/2026-07-06-neiso-wfuelsec-ab-v2.js", "id": "2026-07-06-neiso-wfuelsec-ab-v2", "iso": "NEISO", "label": "neiso wfuelsec ab v2", "shorthand": "neiso-wfuelsec-ab-v2", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "(PROBE, v2-OFF ATTRIBUTION TWIN of neiso-wfuelsec-ab-v2) Winter-fuel Component A + Component B enabled, use_plant_emission_rates_v2 OFF. Isolates the winter-fuel mechanism from the v2 flip per emissions-co2-rate-plan 9.6. RESULT: byte-identical to the v2-on probe on price (dwLMP 31.97/36.08/62.88), fuel mix (COAL 0.062/0.126/0.218, oil 0.35/0.23/1.54 TWh), storage (0.75/0.71/0.91 TWh) and CO2 \u2014 proving use_plant_emission_rates_v2 is fully dispatch-inert for the NEISO backcast (the measured RGGI carbon price times the v2 per-plant rate delta shifts no merit order and moves no scored metric). Confirms the winter-fuel caveats (C1 coal, C3c tail, C5b storage) are unmoved by A+B regardless of the rate basis; keeper stays neiso-48.", "file": "frontend/data/backcast/runs/2026-07-06-neiso-wfuelsec-ab-v2off.js", "id": "2026-07-06-neiso-wfuelsec-ab-v2off", "iso": "NEISO", "label": "neiso wfuelsec ab v2off", "shorthand": "neiso-wfuelsec-ab-v2off", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-06-nyiso-53-li-tsl-ablation", "date": "2026-07-06", "definition": "G-05 forced-energy determination applied 2026-07-07 (keeper unchanged; NO model change). The rule-20 C8 forced-energy breaches on ST_GAS (60.8/69.8/59.7%) and CT_PEAKER (76.2/70.1/39.4%, immaterial/C8-skipped) are adjudicated LEGITIMATE reliability commitments (keep+disclose, caiso-58 precedent). ST_GAS = downstate NYC/LI steamers' genuine persistent 24h base (measured overnight CF 0.11-0.17, online 100% of year; D-1 shape r 0.94). CT_PEAKER binds entirely in its HB14-21 ramp (D-4 off-window 0.0% after correcting the diagnostic window to [14,22)). Confirmed byte-identical at HEAD (re-solve reproduced dispatch exactly). Determination NOT-YET (disclosed hard breach, rule-1 faithfulness). Evidence: docs/handoffs/g05-forced-energy-caiso-ct-nyiso-stgas-2026-07.md. --- L-11 probe: nyiso-52 recipe + Zone-K LCR/TSL import cap (nyiso_li_lcr_tsl, issue #1345 \u2014 replaces the LI 0.45 self-supply floor; published locality import limit, HB14-21 window) + use_plant_emission_rates_v2=True (\u00a79.6 ride-along).", "file": "frontend/data/backcast/runs/2026-07-06-nyiso-53-li-tsl.js", "id": "2026-07-06-nyiso-53-li-tsl", "iso": "NYISO", "label": "nyiso 53 li tsl", "market_story": "ST_GAS +2.7/+3.8/+3.9 TWh and CT_PEAKER +1.1/+0.9/+0.6 TWh vs the zero-forcing twin, displacing CC (-2.3/-3.1/-3.0): NYISO really does commit its downstate steam and peaker fleet out of merit for local reliability (DARU/SRE commitments, steamer minimum-run blocks, the PR-#1442 CAMPD-derived temperature windows) \u2014 behaviour a pure-ED LP cannot produce. Even WITH the floors both classes still under-run the measured actuals (ST_GAS 7.2/8.1/10.3 vs 8.7/11.1/16.0; CT_PEAKER 1.3/1.4/2.4 vs 2.3/2.1/2.8 TWh), so the floors move dispatch toward measured, never past it; the remaining gap is the #1344 reserve-scarcity commitment frontier (data-blocked, Ask-B). The former nyiso_local_selfsupply floor contributes nothing here \u2014 the Zone-K TSL import cap replaced it (issue #1345) and LI energy clears economically.", "shorthand": "nyiso-53-li-tsl", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "(ABLATION TWIN of 2026-07-06-nyiso-53-li-tsl) D-3 zero-forcing twin (rule 21): the keeper recipe verbatim with all merchant floors/bridges zero-forced (protected set only: nuclear must-run, CHP steam, coal take-or-pay). The keeper-vs-twin per-class delta shows what each remaining floor buys.", "file": "frontend/data/backcast/runs/2026-07-06-nyiso-53-li-tsl-ablation.js", "id": "2026-07-06-nyiso-53-li-tsl-ablation", "iso": "NYISO", "label": "nyiso 53 li-tsl (ABLATION TWIN)", "shorthand": "nyiso-53-li-tsl-ablation", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "L-11 probe: nyiso-52 recipe + Zone-K LCR/TSL import cap (nyiso_li_lcr_tsl, issue #1345 \u2014 replaces the LI 0.45 self-supply floor; published locality import limit, HB14-21 window) ; v2 OFF (the \u00a79.6 ablation-resolve twin isolating the v2 flip's contribution).", "file": "frontend/data/backcast/runs/2026-07-06-nyiso53-v2off-twin.js", "id": "2026-07-06-nyiso53-v2off-twin", "iso": "NYISO", "label": "nyiso53 v2off twin", "shorthand": "nyiso53-v2off-twin", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "(PROBE \u2014 NOT a keeper swap; no LP solve) v2 emission-rate re-score of keeper pjm-77-ct-relfloor under use_plant_emission_rates_v2=True. Dispatch/prices/generation are PROVABLY byte-identical (emission_rate enters mc only via emission_rate\u00d7carbon_price; PJM has no state carbon program and backcast carbon_price=0 \u2014 the committed runs.js carries a COMPACT CO2/fuelmix registration payload \u2014 the per-plant panels are omitted (data identical to the keeper's), and the full payload was verified byte-identical to the keeper before compaction). Only CO2 accounting moves. Re-scoring the keeper's persisted per-plant model generation (committed dashboard payload m_ann) through the v2 target-year rate map: COVERAGE 97.4/97.5/97.6% of model fossil GWh now carries a MEASURED plant-specific CO2 rate \u2014 PJM's FIRST measured rates (the legacy plant_emission_rates artifact is TX-only, so pre-v2 every PJM plant booked the generic heat_rate\u00d7FUEL_CO2 default). v2-basis model CO2 268.7/273.1/304.3 Mt (2023/24/25); on the matched plant subset the v2 basis is +2.49/+2.09/+1.56% vs the eGRID+CAMPD-v1 basis \u2014 a small level shift, no distortion. Dashboard C5a verdict UNCHANGED (reads egrid.fossil_co2_rate_map, not v2). Rules #1/#13/#15/#22: no retune, no keeper swap, holdouts untouched (only 2023-2025 read). \u00a79.6 lane L-8b.", "file": "frontend/data/backcast/runs/2026-07-06-pjm-77-v2rescore-probe.js", "id": "2026-07-06-pjm-77-v2rescore-probe", "iso": "PJM", "label": "pjm 77 v2rescore probe", "shorthand": "pjm-77-v2rescore-probe", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "PJM 78 SRMC-cycle baseline: pjm-77 keeper recipe VERBATIM on current HEAD (carries the 2026-07-06 EMAAC CT_CHP tmax limb scrub, burndown \u00a76 option b). Same-SHA comparator for the G-21 sub-SRMC re-grounding A/B (pjm-79); no offer band changed vs pjm-77.", "file": "frontend/data/backcast/runs/2026-07-06-pjm-79-srmc-baseline.js", "id": "2026-07-06-pjm-79-srmc-baseline", "iso": "PJM", "label": "pjm 79 srmc baseline", "shorthand": "pjm-79-srmc-baseline", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "PJM 79 G-21 SRMC re-grounding: pjm-78 baseline recipe with the sub-SRMC residual artifacts re-grounded to the Manual-15 floor \u2014 ST_GAS committed/econ_low/econ_high 0.4752/0.6552/0.90 -> 1.00, CT_INTERMEDIATE committed/econ_low 0.9/0.92 -> 1.00. Grounded move (rule 13/14): a worse fit here is a discovered bug to root-cause, not a reason to revert.", "file": "frontend/data/backcast/runs/2026-07-06-pjm-80-srmc-reground.js", "id": "2026-07-06-pjm-80-srmc-reground", "iso": "PJM", "label": "pjm 80 srmc reground", "shorthand": "pjm-80-srmc-reground", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "(PROBE \u2014 Phase-2 structural validation; keeper stays pjm-77.) PJM 81 per-gen reserve co-opt (G-20 Phase 2): pjm-78 baseline recipe + pjm_reserve_pergen ((zone, fuel-class) pooled R columns \u2014 the miso-39 memory tier: 39 columns / 342k joint rows vs the plant-tier 257/2.25M that OOM'd; P1 now fits the 15 GB box, peak ~15.0 GB with a 10 GB swapfile absorbing a ~0.4 GB transient) + measured_ramp_capability (new ramp-capability datatype: EIA-860 '10M' fast-start floor + CAMPD CEMS max 1-h envelope ceiling on FleetArrays.ramp10; deliverable cap thins ~50 GW -> ~40 GW p50). RESULT: dispatch byte-comparable to pjm-78 at class grain (ST_GAS/CC/CT_PEAKER/COAL_BIT TWh identical to \u00b10.1); verdict criterion-identical (C3a -8.0/-13.3%, C3b 0.175-0.196, C3c 0 h vs 6/18/59, C8 12.0%). The in-LP reserve price is nonzero for the FIRST time in any PJM scoping \u2014 exactly 1 hour (2025-06-23 h19, the June heat wave: $46.47 opportunity-cost dual lifting the year-max LMP to $158.61) vs $0 in all 26,280 hours of every prior variant. Confirms the G-20 diagnosis empirically at the strongest admissible scoping: with ~40 GW measured-deliverable headroom vs the ~3.3 GW requirement, the perfect-foresight pool margin is essentially never tight; the $75-200 afternoon band remains blocked on Phase-1 commitment posture, not on reserve structure, memory, or ramp data. Mechanism retained for the next keeper cycle (rule 1); NOT a promotion case (no criterion gain; C6 unattested, no twin).", "file": "frontend/data/backcast/runs/2026-07-06-pjm-81-coopt-pergen.js", "id": "2026-07-06-pjm-81-coopt-pergen", "iso": "PJM", "label": "pjm 81 coopt pergen", "shorthand": "pjm-81-coopt-pergen", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "PJM 82 commitment-posture A/B probe (L-13 port): pjm-81 per-gen reserve co-opt recipe + pjm_commitment_posture (MISO \u00a7A lever ported, shared code \u2014 non-fast-start pool U/SU columns, CEMS-measured mlf min-load coupling, NREL-class startup charge, online-gated reserve cap R<=ramp10*U). Single-mechanism B arm vs pjm-81 (A, posture off). Zero fitted parameters; honesty-gated on the measured PJM reserve-market series (report_pjm_posture_gate.py).", "file": "frontend/data/backcast/runs/2026-07-06-pjm-82-commitment-posture.js", "id": "2026-07-06-pjm-82-commitment-posture", "iso": "PJM", "label": "pjm 82 commitment posture", "shorthand": "pjm-82-commitment-posture", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "D-3 zero-forcing ablation twin of pjm-80 (CLAUDE.md rule 25): the pjm80_srmc_reground_keeper recipe verbatim with every merchant floor/bridge/drag neutralized (ScenarioConfig.as_zero_forcing_ablation; off-list from the D-2 mechanism registry), structural protected set kept. Registered alongside the keeper for the E9 keeper-vs-twin delta.", "file": "frontend/data/backcast/runs/2026-07-06-pjm-83-reground-ablation.js", "id": "2026-07-06-pjm-83-reground-ablation", "iso": "PJM", "label": "pjm 83 reground ablation", "shorthand": "pjm-83-reground-ablation", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-06-pjm-83-reground-ablation", "date": "2026-07-06", "definition": "KEEPER (promoted 2026-07-06, replacing pjm-77; L-13 lane). Two grounded structural changes on the pjm-77 recipe: (1) G-21 SRMC re-grounding \u2014 the two sub-SRMC residual offer artifacts ST_GAS (committed/econ_low/econ_high 0.4752/0.6552/0.90) and CT_INTERMEDIATE (committed/econ_low 0.9/0.92) move to the Manual-15 composite-cost floor 1.00x. Correct offer physics (rule 1: a non-CHP steam/CT unit's part-load IHR exceeds full-load, so no tranche may clear below 1.0x AHR x delivered fuel \u2014 the floor CC_REGULAR already carries); a sub-SRMC offer is not real and is NOT kept just because it flattered gas volume. (2) CT_CHP EMAAC/Central_PA reliability tmax limbs scrubbed \u2014 all-24h flat floors binding 70.8% off-window (the deciding pjm-77 D-4 failure, 0.0052/0.0095/0.009 TWh); the class's hot-day lift is an all-hours steam-host intensification owned by chp_steam (rule 19). Scrub locked by tests/test_reliability_floor.py::TestPjmCtChpScrubLocked (rule 26). The ct_netload_drag window [15,22) is UNCHANGED: the L-13 overnight-reliability evidence check (diag_pjm_ct_overnight_evidence.py; docs/handoffs/pjm-ct-overnight-evidence-2026-07.md) confirmed overnight CT CF is a flat ~2% net-load-insensitive economic baseline (not reliability) plus a small extreme-net-load uptick 3-5x weaker than the ramp relationship \u2014 widening the hinge overnight would over-floor 2-3x; the extreme-net-load overnight duty is owned by reserve/ORDC (G-20 Phase 2, memory-gated). PROMOTED ON STRUCTURE (rule 1: keeper = most structurally faithful, not lowest MAE). Legitimacy improves vs pjm-77: D-4 CT_CHP failure RESOLVED (only residual is reliability_floor x CT_PEAKER 0.0002 TWh in 2023, a mixed-fuel-plant class-aggregation artifact \u2014 solve floors carry ZERO CT_PEAKER reliability, the drag owns the class and is 0% off-window); D-2 PASS at rubric v2.1 (CT_PEAKER 9.2/14.5/10.2% < 15% peaker budget). Determination NOT-YET (same class as pjm-77). DISCLOSED CALIBRATION TRADEOFF (rule 14, tracked as issue #1483, NOT a reason to revert): de-flooding ST_GAS relocates ~14 TWh/yr \u2014 2023 CC_REGULAR IMPROVES (-19.8 to -9.9 TWh) but 2024 CC over-runs (+13.5 TWh) and 2025 coal +6.2% (a new C2 sysvol FAIL vs pjm-77); real ST_GAS runs far more than a pure-efficiency merit order clears, an unmodeled RMR/local-deliverability driver. Price mean/tail and CT under-dispatch unchanged (the memory-blocked per-gen reserve/ORDC item, G-20 Phase 2). Zero-forcing ablation twin registered (2026-07-06-pjm-83-reground-ablation): all merchant floors to 0, CT_PEAKER total barely moves (drag does timing/shape, not net volume). See docs/calibration-log.md and docs/handoffs/pjm-ct-overnight-evidence-2026-07.md.", "file": "frontend/data/backcast/runs/2026-07-06-pjm-83-srmc-reground.js", "id": "2026-07-06-pjm-83-srmc-reground", "iso": "PJM", "label": "pjm 83 srmc reground", "shorthand": "pjm-83-srmc-reground", "years": [2023, 2024, 2025]}, {"date": "2026-07-07", "definition": "PROBE (G-15 scarcity-tail candidate \u2014 REJECTED as the drag's second half; also the G-20a settlement-basis vehicle and the caiso-62 A/B base arm). Byte-faithful caiso-60 keeper replay at HEAD (drag ON, RA must-offer P1-native, P1-scored; LP identical to the keeper recipe \u2014 caiso_scarcity_pricing is post-solve-only in a backcast, and the recorded dirty diff is the default-off #1492 reserve code, inert here with the co-opt off and modules imported pre-edit). Carries the derived scarcity.parquet (derive_caiso_scarcity_overlay.py: VOLL $2,000 Tariff \u00a739.6.1, MCL 1,400 MW Diablo MSSC, \u03c3 2,500 MW FRP \u2014 published params, zero fitted) so C3c scores the SETTLEMENT price (G-20a owner-approved basis). RESULT \u2014 the published LOLP overlay is INERT exactly where the tail deficit is: 2024 adder mean $0.04 (0 h >$100, tail 0 h vs 52 h DA), 2025 mean $0.01 (0 h, 0 vs 8 DA small-count PASS), and ADDITIVE only to 2023's evening-merit-owned over-tail (mean $0.54, 10 h >$100; settlement 511 h vs energy-only 502 h vs 41 h DA / 21 h RT). Confirms G-20d: the CAISO tail miss is evening-merit / seam-shape, not reserve scarcity \u2014 see FINDING-caiso-seam-diurnal-2026-07-07.md (midday/evening/overnight seam misshape vs measured EIA-930: model near-flat 2.4-5.1 GW vs actual 5:1 swing; evening +2-3.2 GW over-import suppresses the premium the drag must then carry). Overlay mechanism stays built + default-off (rule 1); keeper stays caiso-60.", "file": "frontend/data/backcast/runs/2026-07-07-caiso-61-lolp-tail.js", "id": "2026-07-07-caiso-61-lolp-tail", "iso": "CAISO", "label": "caiso 61 lolp tail", "shorthand": "caiso-61-lolp-tail", "years": [2023, 2024, 2025]}, {"date": "2026-07-07", "definition": "PROBE (#1492 reserve co-opt COMPLETED \u2014 participation model per the issue's own design constraints 2/3; fully inert, kept default-off per rule 1; keeper stays caiso-60). The caiso-60 keeper recipe + energy_reserve_coopt + caiso_reserve_coopt with the extension this branch adds: STORAGE backs the co-drawn spin/non-spin requirement through duration-gated RS[c,z] columns on the pergen path (power competition vs its own charge/discharge + the published 30-min ASSOC state-of-charge sustain, CAISO_AS_SUSTAIN_DURATION_H=0.5 h, Tariff AS certification), and HYDRO joins the CAISO-local pergen pool (166 plants; CAISO_HYDRO_RAMP10_FRAC=1.0 backfill, WWSIS-2 class physics) \u2014 1,249 eligible units, 14 (zone,fuel) pools, \u03a3 19.2 GW deliverable ramp vs a ~2.24 GW BAL-002-WECC-3 requirement (max(MSSC, 6% load), half/half; \u00a727.1.2.3.5 demand curves; zero fitted breakpoints). RESULT vs the caiso-61 base arm at the same HEAD: reserve price fired 0 h in ALL years (caiso-59's thermal-only build fired ~100 h 2023 up to $800 \u2014 completing the real provider set removed even those), mean \u03bb unchanged \u00b1$0.00, C3c tail unchanged. This is the pre-registered honest direction (issue #1492: participation ADDS supply; the thermal-only pool over-stated scarcity; real CAISO AS prices are ~$0 in most hours). Confirms the G-20 Layer-2 unifying root cause: the perfect-foresight LP is never reserve-tight, so no correctly-parameterized reserve mechanism can source the 2024/25 tail. Residual #1492 scope: Regulation Up/Down (no forward-derivable requirement series).", "file": "frontend/data/backcast/runs/2026-07-07-caiso-62-coopt-full.js", "id": "2026-07-07-caiso-62-coopt-full", "iso": "CAISO", "label": "caiso 62 coopt full", "shorthand": "caiso-62-coopt-full", "years": [2023, 2024, 2025]}, {"date": "2026-07-07", "definition": "PROBE (G-61 path (b) \u2014 startup-aware RA-bridge run detection; keeper stays caiso-60, adoption = owner decision). The caiso-60 keeper recipe + caiso_ra_bridge_startup_aware: a base-cost P0 run anchors a bridge only when COMMITMENT-REAL under the unit's own start economics (run margin per MW of capacity >= the published class startup cost) \u2014 the phantom micro-runs the startup-free P0 manufactures stop chopping the solar belly into sub-min-down gaps that floored unconditionally. Zero fitted parameters (P0 economics + NREL/CAMPD-bin startup costs; rules 13/17). RESULT vs the caiso-61 base arm: RA-bridge forced energy drops ~40% (4.04/4.01/3.48 -> 2.56/2.33/2.38 TWh; peak simultaneous floor 2,483/2,820/2,629 -> 2,378/2,364/1,917 MW) \u2014 1.5-1.7 TWh/yr of belly min-load holds were phantom-anchored. The freed CC largely re-dispatches on merit (class -0.5 TWh), CT evening is UNCHANGED (712/636/449 -> 713/636/450 MW \u2014 the drag owns CT; cheap CC returns on merit), and the body prices rise slightly (mean lambda +$0.45/+0.46/+0.30, midday +$0.50-0.93 \u2014 the phantom floors were price-suppressing; 2023 tail 502->530 h). Structure-first tradeoff (rule 1): strictly more faithful UC physics and a ~40% smaller C8/D-2 forcing budget for the RA bridge, at a small honest C3a cost in an already-overpriced body whose root cause is the WECC seam shape (FINDING-caiso-seam-diurnal-2026-07-07). G-61a context: the quantity gate proved a measured no-op (bridged fleet 13.7-13.8 GW < published 19.1/15.6/15.6 GW), so detection realism \u2014 this probe \u2014 is the live G-61 lever.", "file": "frontend/data/backcast/runs/2026-07-07-caiso-63-g61b-startup.js", "id": "2026-07-07-caiso-63-g61b-startup", "iso": "CAISO", "label": "caiso 63 g61b startup", "shorthand": "caiso-63-g61b-startup", "years": [2023, 2024, 2025]}, {"date": "2026-07-07", "definition": "PROBE (G-61 path (c) \u2014 curtailed-VRE-volume release; MEASURED FULLY INERT, kept default-off per rule 1; keeper stays caiso-60). The caiso-60 keeper recipe + caiso_ra_bridge_curtailment_release: a bridge gap containing an hour of genuine P0 renewable curtailment (wind+solar dispatched below available potential, 1 MW float-noise guard) never floors \u2014 the volume form of the D-8 closure \u00a77 price-based release (which was correct in isolation but inert because the midday LMP never reaches the curtailment floor). RESULT vs the caiso-61 base arm: BYTE-IDENTICAL floors, dispatch and prices in all three years \u2014 the base-cost P0 never curtails a single MWh of wind/solar in any hour of 2023-2025, so the release condition never fires. This is the pre-registered expectation (FINDING-caiso-seam-diurnal-2026-07-07: the WECC seam under-imports midday by 1-1.8 GW, keeping the model gas-marginal through the belly and starving every curtailment-based signal). The mechanism is real market design (CAISO decommits RA units in oversupply rather than curtail more VRE) and stays built for the day the seam-shape fix lands; its inertness is itself the measured coupling evidence for G-61 <- seam (G-15 residual).", "file": "frontend/data/backcast/runs/2026-07-07-caiso-64-g61c-curtail.js", "id": "2026-07-07-caiso-64-g61c-curtail", "iso": "CAISO", "label": "caiso 64 g61c curtail", "shorthand": "caiso-64-g61c-curtail", "years": [2023, 2024, 2025]}, {"date": "2026-07-07", "definition": "D-3 zero-forcing ablation TWIN of caiso65_seam_envelope_clock (rule 21): the same envelope-clock-corrected caiso-60 recipe with every merchant floor/bridge neutralized (ScenarioConfig.as_zero_forcing_ablation). ablation_of: caiso65_seam_envelope_clock (recorded here; the replay path does not thread the run_config field - see the W3a PR).", "file": "frontend/data/backcast/runs/2026-07-07-caiso65-seam-envclock-ablation.js", "id": "2026-07-07-caiso65-seam-envclock-ablation", "iso": "CAISO", "label": "caiso65 seam envclock ablation", "shorthand": "caiso65-seam-envclock-ablation", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-07-caiso65-seam-envclock-ablation", "date": "2026-07-07", "definition": "KEEPER (promoted 2026-07-07, owner decision; supersedes caiso-60 - same recipe, corrected envelope clock). The caiso-60 keeper recipe re-solved with the measured (month x hod) p95 corridor envelope bucketed on the MODEL clock: the CISO per-DIBA parquet's local_time stamps lag the model frame by a measured 1h (standard) / 2h (daylight) - lag-scan corr 0.972/0.961 at -1/-2h vs <=0.930 elsewhere, absolute frame anchored by January solar astronomy + the 2024-04-08 eclipse dip - so the keeper's envelope reached the LP 1-2h late. Fixed at the read seam (eia_loader._caiso_interchange_model_clock, pinned measured constants + drift guard scripts/validate_caiso_seam_hod_frame.py; zero fitted parameters, rule 23). A/B vs the caiso-61 base arm at the same code state: hod-mean corridor-flow error improves every year (mean |delta| 1402->1362 / 1803->1692 / 1979->1816 MW, gains at the phase edges h9/h18), lambda a near-wash (+-$0.0-0.8) as pre-registered; kept on correctness (rule 14). Part of the W3a forensics that WITHDREW the seam-diurnal FINDING attribution (its actual-flow table was UTC-bucketed) and reattributed the C3a body to belly gas commitment - see FINDING-caiso-seam-tz-correction-2026-07-07.md. Promotion disclosures: determination stays NOT-YET, unchanged from caiso-60. Of the 12 C-gates, 11 are unchanged and one moves: C2 system volume FAIL->CAVEAT (commercial-band), lifting the grade summary from scored 9/target 2/commercial 0/fails 7 (caiso-60) to commercial 1/fails 6 (caiso-65) - a real one-criterion gain from the corrected envelope, not identical to the caiso-60 lineage. C1 free-class 7/8->6/8 - 2023 CC_REGULAR crosses the band edge as the corrected envelope trims ~0.3-0.5 GW of phantom morning imports that backfill mostly with CC (fix-real: CI/local dispatch byte-identical across highspy 1.15.1/1.14.0, so not solver drift). C8 CT_PEAKER FAIL inherited from the caiso-58/60 lineage (owner-held per the G-11 decision). C6 stays UNATTESTED, inherited unchanged from caiso-60: calibration_attestation.json carries the caiso-60 DOF ledger plus the two new measured clock-lag constants, but the attestation still has no governance block. Ablation twin: 2026-07-07-caiso65-seam-envclock-ablation.", "file": "frontend/data/backcast/runs/2026-07-07-caiso65-seam-envelope-clock.js", "id": "2026-07-07-caiso65-seam-envelope-clock", "iso": "CAISO", "label": "caiso65 seam envelope clock", "shorthand": "caiso65-seam-envelope-clock", "years": [2023, 2024, 2025]}, {"date": "2026-07-07", "definition": "G-22 online-capacity envelope A/B: TREATMENT arm = ercot34 recipe + ercot_online_capacity_envelope=True (single delta). Committed on-line HSL caps the co-opt shared-headroom energy+reserve so the LP cannot serve/reserve more thermal than the real system had on-line \u2014 removes the phantom sub-200 spare (FINDING structural conclusion #2). deliv=1.083 fit to reproduce measured RTOLCAP in the binding regime on the production cap basis (within +/-2%); no offer-height change (rule 1). PROBE.", "file": "frontend/data/backcast/runs/2026-07-07-ercot41-envelope-on-probe.js", "id": "2026-07-07-ercot41-envelope-on-probe", "iso": "ERCOT", "label": "ercot41 envelope on probe", "shorthand": "ercot41-envelope-on-probe", "years": [2023, 2024, 2025]}, {"date": "2026-07-07", "definition": "ercot42 zero-forcing ablation twin: WP-B driver wired but depth=0 (inert) \u2014 isolates the depth coefficient from the LP wiring (rule 21)", "file": "frontend/data/backcast/runs/2026-07-07-ercot42-wtx-curtailment-ablation.js", "id": "2026-07-07-ercot42-wtx-curtailment-ablation", "iso": "ERCOT", "label": "ercot42 wtx curtailment ablation", "shorthand": "ercot42-wtx-curtailment-ablation", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-07-ercot42-wtx-curtailment-ablation", "date": "2026-07-07", "definition": "ercot42: WP-B West Texas Export corridor net-load-indexed VRE curtailment-share driver (nodal congestion ceiling) on the ercot34 keeper recipe, single delta ercot_wtx_curtailment_driver=True (depth wind 0.0998 / solar 0.1633; SHAPE = measured NP6-86 West-corridor binding frequency via the NP4-160 SP crosswalk; docs/handoffs/ercot-vre-curtailment-wpb-driver-2026-07.md). PROMOTED TO KEEPER 2026-07-07 (owner GO in-session; ercot_wtx_curtailment_driver flipped to the ERCOT backcast default, tri-state at the orchestrator seam with a pre-driver replay backstop). Full promotion gate: byte-faithful re-solve reproduced the registered metrics exactly; full scored bundle committed (legitimacy_diagnostics D-1/D-2/D-5/D-9/D-10 PASS, D-4 FAIL inherited unchanged from the keeper's reliability_floor x CT_PEAKER rows; stage4_gate_eval vs keeper + RT actuals; C6 attestation with the DOF ledger carrying the ONE outcome-anchored DOF - the depth pair, owner-accepted 2026-07-07 as a documented ASSUMPTION with ReEDS/Cambium/NEMS/Aurora/IPM reduced-form-curtailment precedent + RTOLCAP-deliv identification). VERDICT: NOT-YET on the same two pre-existing criteria as the keeper (C3b/C3c) - no new criterion-level fail; grade summary strictly better (target-grade 7 vs 6, ledgered 0 vs 1: C5c-2024 improves to genuine PASS r>0.50). C2 gas closes ~2pp/yr; [3e] wind curtailment doubles toward reported. ATTRIBUTION vs the depth=0 ablation twin (same HEAD code+data): the C3b-2024 flip (0.225 ablation vs 0.252 probe, thr 0.20), the C3c-2025 tail collapse (1h in both) and most of the Aug-2024 price rise (+13.2 of +16.4) are the 2024/25 measured-HSL intake's data-vintage effect, present with the driver OFF; the driver itself ADDS +3.4 Aug-2024, moves 2023 prices toward actual (C3b-2023 0.324->0.256), and RESCUES C2-2025 from the intake-induced FAIL (-6.4% ablation) back into the commercial band (-4.0%). C3a 2023/2024 move PASS->CAVEAT (+8.9%/+6.6%, commercial band) - the driver's price footprint. LOYO VERDICT SCORING (rule 19/22, train-only share table + depths, throwaway single-year solves): every year-level verdict reproduces under LOYO (C3a +10.0/+6.5/+3.2 vs pooled +8.9/+6.6/+3.2; C3b 0.264/0.251/0.085 vs 0.256/0.252/0.085; C3c 105/24/1 vs 103/24/1; C2 gas -5.6/-5.6/-6.0 vs -5.9/-5.7/-6.3) - no verdict flip is an in-sample artifact; 2023 C3a sits at the commercial-band edge (+10.0%) under LOYO. Forecast leg wired this session (runner.py DispatchSpec seam + reference-rate gross-up; two documented assumptions: percentile normalization pins decile-conditional depth at the 2023-25 level; frozen 2023-25 West topology). Supersedes ercot34-stage4-overlay-off.", "file": "frontend/data/backcast/runs/2026-07-07-ercot42-wtx-curtailment-driver.js", "id": "2026-07-07-ercot42-wtx-curtailment-driver", "iso": "ERCOT", "label": "ercot42 wtx curtailment driver", "shorthand": "ercot42-wtx-curtailment-driver", "years": [2023, 2024, 2025]}, {"date": "2026-07-07", "definition": "G-22 extreme-peak-resolved envelope A/B: CONTROL arm = ercot42 keeper recipe replayed byte-faithfully at HEAD (no delta). Baseline for the ercot_online_capacity_envelope_extreme treatment; doubles as the zero-forcing ablation twin of the extreme envelope.", "file": "frontend/data/backcast/runs/2026-07-07-ercot43-extremeenv-off.js", "id": "2026-07-07-ercot43-extremeenv-off", "iso": "ERCOT", "label": "ercot43 extremeenv off", "shorthand": "ercot43-extremeenv-off", "years": [2023, 2024, 2025]}, {"date": "2026-07-07", "definition": "G-22 extreme-peak-resolved envelope A/B: TREATMENT arm = ercot42 keeper recipe + ercot_online_capacity_envelope_extreme=True (single delta). 14-bin extreme-resolved share + per-bin deliverability fit to the measured thermal on-line HSL identity (CAMPD gross + RTOLCAP - storage AS - LR credit); identification gate PASSED (binding -0/+3/-2%, pooled top-2% exact, per-year extreme ledger -23/-2/+18%). PROBE.", "file": "frontend/data/backcast/runs/2026-07-07-ercot43-extremeenv-on-probe.js", "id": "2026-07-07-ercot43-extremeenv-on-probe", "iso": "ERCOT", "label": "ercot43 extremeenv on probe", "shorthand": "ercot43-extremeenv-on-probe", "years": [2023, 2024, 2025]}, {"date": "2026-07-07", "definition": "ercot44 HSL-clock-fix A/B: TREATMENT arm = ercot42 keeper recipe replayed at HEAD, single delta = the rebuilt 2024/2025 HSL parquets (CPT->CST clock fix in scripts/build_ercot_hsl.py; NP4-732/737 stamps are Central Prevailing Time and were placed on the standard-time model clock unconverted, putting the whole Mar-Nov wind/solar potential one hour late -- Jan lag 0 / Jul lag +1 vs EIA-930, r=1.0000). Control = registered 2026-07-07-ercot43-extremeenv-off. Rule-23 source citation: placement defect in this repo's intake, ERCOT source data unchanged. (PROBE, NOT-YET/unattested.) VERDICT vs the control: C3b-2024 0.252 FAIL -> 0.180 commercial-band CAVEAT (C3b now fails only on 2023 0.256); C3c moves toward actual in both intake-affected years (2024 24->28h = 0.41x DA, 2025 1->5h = 0.22x DA; 2023 unchanged 103h, byte-identical arm legs); C2-2025 gas -4.0 -> -3.8%; C3a-2024 +6.6 -> +5.9%. Two rule-14 discovered compensations opened as root-cause items (docs/handoffs/ercot-g22-demand-side-design-2026-07.md s6.2): C3a-2025 +3.2 -> +7.1% (stays commercial band) and C5c-2024 storage monthly shape r 0.518 -> 0.481 (PASS -> FAIL). The corrected parquets are the standing input regardless (rule 14); keeper decision owner-pending.", "file": "frontend/data/backcast/runs/2026-07-07-ercot44-hsl-clock-fix.js", "id": "2026-07-07-ercot44-hsl-clock-fix", "iso": "ERCOT", "label": "ercot44 hsl clock fix", "shorthand": "ercot44-hsl-clock-fix", "years": [2023, 2024, 2025]}, {"date": "2026-07-07", "definition": "ercot44b control: byte-faithful replay of the ercot42 keeper recipe (via the ercot43 control bundle) at HEAD code on the PRE-clock-fix measured parquets/share-table/depths (origin/main data state) - the A arm of the clock-unification + ST_GAS stepwise A/B/C.", "file": "frontend/data/backcast/runs/2026-07-07-ercot44b-control.js", "id": "2026-07-07-ercot44b-control", "iso": "ERCOT", "label": "ercot44b control", "shorthand": "ercot44b-control", "years": [2023, 2024, 2025]}, {"date": "2026-07-07", "definition": "(ABLATION TWIN of 2026-07-07-miso-45-cc-capacity) miso-45 zero-forcing ablation: identical recipe (incl. the CC demonstrated-capacity cap) with every merchant floor/bridge OFF. Keeper-minus-twin per-class deltas <=0.05 TWh (floors force <0.6 TWh; nothing floor-bought in the CC row).", "file": "frontend/data/backcast/runs/2026-07-07-miso-45-ablation.js", "id": "2026-07-07-miso-45-ablation", "iso": "MISO", "label": "miso 45 ablation", "shorthand": "miso-45-ablation", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-07-miso-45-ablation", "date": "2026-07-07", "definition": "miso-45 (G-23 root-cause fix): miso-44 recipe + cc_capacity_reconcile with the MISO demonstrated-capacity cap table (derive_cc_capacity_reconcile.py --iso MISO --mode cap). Root cause of the CC_REGULAR +20 TWh overrun: EIA-860 reports 7 MISO CC plants' steam (CA) rows with BLOCK-level Summer Capacity while nameplate stays component-level; the loader's summer-preferred pmax double-counts the CTs (-2,714 MW phantom, 6 of 7 plants MISO-South, e.g. Union Power 3,457 MW modeled vs 2,428 nameplate / 2,318 CAMPD p99.9 / 2,354 EIA-860 winter). Cap = plant's own measured CAMPD p99.9 sustained peak - zero new DOF. RESULT vs miso-44: CC_REGULAR +20.0/+19.1/+3.1 -> +6.7/+7.2/-7.3 TWh; ST_GAS -8.5/-11.0/-10.5 -> -2.0/-4.6/-6.1; C1 12/16 -> 15/16 (free 8/12 -> 11/12); C3b PASS. 2025 residual moves onto the open import-starvation + coal-sigmoid rows (audit boxes 3-4). Full audit: docs/multi-iso/miso-cc-overrun-rootcause-2026-07.md. Determination stays NOT-YET (same class as miso-44): four load-bearing/supporting FAILs remain open \u2014 C1 2024 ST_GAS -9.87 TWh; C2 2025 gas -10.8% / coal +16.8%; C3a 2025 mean LMP -10.5%; C3c 2024/2025 scarcity-tail hours model 0h vs DA actual 24h/38h \u2014 plus a C5a CO2 CAVEAT (commercial-band, 2025 +7.1%) and C5b/C5c storage CAVEATs (ledgered: MISO's EIA-930 series carries no pumped-storage breakout, so the model's PS+battery discharge is scored against a battery-only actual). The promotion is on the CC-capacity root-cause fix and DOF reduction, not on these FAILs or caveats closing.", "file": "frontend/data/backcast/runs/2026-07-07-miso-45-cc-capacity.js", "id": "2026-07-07-miso-45-cc-capacity", "iso": "MISO", "label": "miso 45 cc capacity", "market_story": "Floors force <0.6 TWh total (all four enabled MISO limbs are design-day commitment floors: hot-day coal/CT/ST_GAS units are online before the peak because operators commit against the design cooling/heating day, not the price of the hour). The miso-45 keeper-vs-twin per-class deltas are near-zero by construction - the run's structural content is the measured demonstrated-capacity cap, which is in BOTH twins; nothing in the CC row is floor-bought.", "shorthand": "miso-45-cc-capacity", "years": [2023, 2024, 2025]}, {"date": "2026-07-07", "definition": "(ATTRIBUTION ARM for 2026-07-07-miso-46-seam-ladder; ercot36 pattern, not a keeper) miso-45 keeper recipe replayed byte-faithfully at HEAD with NO config delta - isolates main's merged drift since the keeper SHA 86601ce (chiefly the owner-directed cc_duct_peaking all-ISO default extension 7358028) from the miso-46 measured-seam-ladder single delta. RESULT: (a) HEAD drift alone (this arm vs miso-45-committed): net interchange 35.1->36.0/15.5->16.0/3.4->4.0 TWh, 2023 COAL_PRB 122.1->122.8 (+0.7 - the duct drift is what pushes the pre-existing +7.4 overrun to the +8.34 C1 band edge, NOT the ladder); (b) the LADDER single delta (miso-46 vs this arm): 2023 near-no-op (net 36.0->35.2, PRB +0.1), 2024 net +3.6 (16.0->19.6; PRB -1.9, CT -0.7, ST_GAS -0.6), 2025 net +9.2 (4.0->13.2; CT -2.6, CC -2.2, PRB -1.8, ST_GAS -1.2, BIT -1.0) - the 2025 restored imports displace gas ~2:1 over coal, confirming the coal-sigmoid re-attribution (#1347). Unattested by design (attribution probe, not a keeper candidate).", "file": "frontend/data/backcast/runs/2026-07-07-miso-45-head-replay.js", "id": "2026-07-07-miso-45-head-replay", "iso": "MISO", "label": "miso 45 head replay", "shorthand": "miso-45-head-replay", "years": [2023, 2024, 2025]}, {"date": "2026-07-07", "definition": "(ABLATION TWIN of 2026-07-07-miso-46-seam-ladder) miso-46 zero-forcing ablation: identical recipe (incl. the measured seam ladders + cc capacity cap) with every merchant floor OFF (reliability_floor=false, the MISO zero-forcing delta; run_config carries a post_hoc recording-fidelity correction - the solve is proven floor-off: no floor log line + nonzero deltas where same-config replays are byte-identical). Keeper-minus-twin per-class deltas <=0.06 TWh (2023 COAL_BIT 0.06 is the max; floors force <0.6 TWh; nothing in the import/coal story is floor-bought).", "file": "frontend/data/backcast/runs/2026-07-07-miso-46-ablation.js", "id": "2026-07-07-miso-46-ablation", "iso": "MISO", "label": "miso 46 ablation", "shorthand": "miso-46-ablation", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-07-miso-46-ablation", "date": "2026-07-07", "definition": "miso-46 (G-23 residual root-cause fix): miso-45 keeper recipe + miso_seam_measured_ladder at HEAD (single --set delta via replay_keeper; HEAD also carries the owner-directed cc_duct_peaking default extension 7358028, in ANY new run). Root cause (docs/multi-iso/miso-import-starvation-rootcause-2026-07.md): the measured PJM+IESO seam is a firm/scheduled base - imports in 97.5-99.5% of ALL hours, hourly flow uncorrelated with the RT spread (r=+0.06), 2025 mean RT spread $0.00 while 28 TWh flowed, 46-56% of import MWh inside the $2 hurdle - which hurdle-gated spot-spread pricing structurally deletes in a zero-spread year (miso-45 2025: 3.4 TWh gross imports vs 19.0 actual net, displaced onto +22 TWh PRB - the C2 FAIL). Fix = the NEISO audit-C-6 measured-ladder pattern on MISO's three seams (interchange_config.MISO_SEAM_LADDER_BY_YEAR, frozen scripts/derive_miso_seam_ladders.py: EIA-930 per-seam flow durations Q-Q coupled with the measured MISO DA hub LMP on the existing 8-band grid; zero fitted parameters, rule 23; envelopes/capacities/Manitoba unchanged; every band clears economically on the model's own hourly price - contrast the rejected miso_firm_import_floor pin). RESULT vs miso-45: net interchange +35.2/+19.6/+13.2 TWh vs actual +37.9/+23.1/+19.0 (was +35.1/+15.5/+3.4); 2025 PJM-seam imports 1.4 -> 16.7 TWh; South exports restored -5.7/-8.4. Trade-off surfaced (rule 14 - removing a compensating error): the restored imports displace GAS not PRB (model PRB undercuts even the $21.82 base rung): C2-2025 gas -10.8 -> -14.1% / coal +16.8 -> +15.7% (both FAIL), C3a -10.5 -> -11.8%, C3b PASS -> commercial caveat (NRMSE 0.168), C1 15/16 -> 14/16 (2023 COAL_PRB +7.4 -> +8.34 crosses the band edge; 2024 ST_GAS -10.05 unchanged-ish). The ~+30 TWh dear-gas coal-vs-gas mis-order re-attributes to the coal-sigmoid offer level (#1347, C-1 ledgered DOF - NOT refit, rule 23) + the 0h scarcity tail (G-20e data-blocked). DOF ledger: seam family flips residual -> measured-physical (5 entries / 3 residual at HEAD). Determination NOT-YET (same class as miso-45). Same-box replay determinism: byte-identical dispatch/system/flows on a full re-solve. Memory (G-40): VmHWM 14.85 GB yr-1 / 15.76 GB yr-2 peak; OOM-killed at 15.95 GB without swap on a 15 GiB box; completes with a 10 GiB swapfile (<=190 MB swapped). KEEPER PROMOTED 2026-07-07 (owner decision, gap-review session): structure-over-fit per rules 1/14 \u2014 the seam ladder is measured physical structure and the fit regression is the disclosed compensating-error re-attribution to #1347; pjm-83 precedent. Supersedes miso-45-cc-capacity as MISO keeper.", "file": "frontend/data/backcast/runs/2026-07-07-miso-46-seam-ladder.js", "id": "2026-07-07-miso-46-seam-ladder", "iso": "MISO", "label": "miso 46 seam ladder", "shorthand": "miso-46-seam-ladder", "years": [2023, 2024, 2025]}, {"date": "2026-07-07", "definition": "Zero-mechanism ablation twin of neiso53_winter_coldsnap_ab: all three winter-fuel mechanisms off (= neiso-50 keeper baseline), same harness/BTM basis, for D-3 attribution of the winter stack.", "file": "frontend/data/backcast/runs/2026-07-07-neiso53-winter-fuelsec-ablation.js", "id": "2026-07-07-neiso53-winter-fuelsec-ablation", "iso": "NEISO", "label": "neiso53 winter fuelsec ablation", "shorthand": "neiso53-winter-fuelsec-ablation", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-07-neiso53-winter-fuelsec-ablation", "date": "2026-07-07", "definition": "G-24 NEISO winter fuel-security adoption on the neiso-50 base: three real ISO-NE winter mechanisms turned on together - gas cold-snap availability derate (TDFOR) + Component A oil-inventory budget + Component B fuel-secure must-run (WRP/IEP/OFSA + NERC Winter Storm Elliott). On 2023-2025 they are DORMANT on every scored metric (C3c/C5b unmoved, prices byte-near-identical to the ablation twin): the ample NEISO winter fleet never goes reserve-short under a <=13%-on-8-hours derate and the dual-fuel oil-parity cap (~$258) holds, so Component A never binds. Component B does commit the immaterial fuel-secure COAL fleet on cold days (<0.3% ISO load, reported-not-gated, rule 20 v2.1). Adopted for FORWARD faithfulness (rule 1: real, forward-responsive structure stays in even when the backcast residual does not move; binds in colder forecast years). Same determination as neiso-50 (CALIBRATED-WITH-CAVEATS). Refutes the hypothesis that a missing winter mechanism drives the C3c/C5b residual - that is a NEISO winter capacity-adequacy / scarcity-price-formation gap.", "file": "frontend/data/backcast/runs/2026-07-07-neiso53-winter-fuelsec-coldsnap.js", "id": "2026-07-07-neiso53-winter-fuelsec-coldsnap", "iso": "NEISO", "label": "neiso53 winter fuelsec coldsnap", "market_story": "The NEISO winter fuel-security stack (cold-snap gas derate + oil-inventory budget + fuel-secure must-run) is structurally faithful but DORMANT on every scored 2023-2025 metric: vs the zero-mechanism twin, C3c stays 0h >$300 (max ~$258, oil-parity cap), 2025 storage moves 0.697->0.715 TWh (+2.6%), winter oil +0.8%, Component A oil budget never approached (~3.3 of 9.79 M MMBtu/month). Component B does commit the tiny fuel-secure COAL fleet on cold days (D-2 forced 0.35/0.23/0.02 vs 0.0 in the twin) but COAL is <0.3% of ISO load - reported-not-gated. The C3c tail / C5b storage residual is a capacity-adequacy / price-formation gap, not a fuel-security-mechanism gap - the mechanisms are kept on for the colder forecast years they would bind in, not to move this backcast.", "shorthand": "neiso53-winter-fuelsec-coldsnap", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-07-nyiso-55-ldc-transport-ablation", "date": "2026-07-07", "definition": "(CANDIDATE \u2014 G-13 RESOLVED; keeper stays 2026-07-06-nyiso-53-li-tsl pending owner promotion) The nyiso-53 keeper recipe with the downstate CT-peaker gas re-grounded on the CORRECT rate-class, per-zone measured delivered index (nyiso_downstate_ct_gas_daily; nyiso-downstate-gas datatype v2). The LM6000 downstate peakers are non-firm TRANSPORTATION customers, so their delivered fuel = Transco Z6 NY daily commodity + the LDC monthly non-firm transportation delivery rate (KEDNY SC-22 for NYC, KEDLI SC-19 for Long Island; National Grid statnfdr statements, fetched free from the tariff archive). This is the Ask-A LI/NYC delivered-gas intake the G-13 register row called for; it supersedes nyiso-54's statewide EIA-N3050NY3 firm-citygate stand-in with the correct rate class at the correct per-zone boundary (rules #1/#11/#12/#13), zero new free parameters. RESULT vs nyiso-53: C1 fuel-mix PASS all 14/14 classes (the CT_PEAKER over-run is NOT reintroduced), C2 PASS, C3c price-tail PASS, C5 dispatch-corr PASS, C7 shape PASS; C3a/C3b/C8 unchanged from the keeper (nyiso-53 ledgers these same values as accepted #1344/Ask-B-blocked caveats). A metrics WASH but strictly more structurally faithful: the correct delivered-fuel boundary no longer being the open root cause is the deliverable, and the residual downstate scarcity level/tail is reattributed to #1344/Ask-B (endogenous reserve-scarcity commitment), a distinct data block. NOT-YET here is solely the missing governance attestation (a keeper-promotion step), not a metrics regression.", "file": "frontend/data/backcast/runs/2026-07-07-nyiso-55-ldc-transport.js", "id": "2026-07-07-nyiso-55-ldc-transport", "iso": "NYISO", "label": "nyiso 55 ldc transport", "market_story": "Re-grounding the downstate CT gas on the correct per-zone non-firm TRANSPORTATION delivered index (Transco Z6 NY daily commodity, up to ~$100/MMBtu on Jan-2025 arctic days, + KEDNY SC-22 ~$2.5-3.4/MMBtu for NYC / KEDLI SC-19 ~$1.7-2.9/MMBtu for Long Island) lifts the peaker offer on the exact scarce days it runs and prices NYC peakers above LI ones, which is the delivered-fuel physics a pure-ED LP should honor. Vs the zero-forcing twin, the PR-#1442 windowed temperature floors still commit downstate CT_PEAKER (2023 ~88% of class energy) and ST_GAS out of merit for local reliability \u2014 behaviour a pure-ED LP cannot produce. But the correct gas boundary cannot move the >$300 tail or the mean-price level: the peakers the real market commits for reserve sit idle in the pure-ED LP (issue #1344, data-blocked on the Ask-B condition-varying reserve-requirement series), so pricing their gas correctly is a structurally-faithful refinement that leaves the masked residual where it is (rule #1). Kept honest: no offer markup, adder, or floor is tuned to close the gap (rules 13/26).", "shorthand": "nyiso-55-ldc-transport", "years": [2023, 2024, 2025]}, {"date": "2026-07-07", "definition": "(ABLATION TWIN of 2026-07-07-nyiso-55-ldc-transport) D-3 zero-forcing ablation twin (rule 21) of the per-zone LDC-transport candidate: the candidate recipe verbatim with all merchant floors/bridges zero-forced.", "file": "frontend/data/backcast/runs/2026-07-07-nyiso-55-ldc-transport-ablation.js", "id": "2026-07-07-nyiso-55-ldc-transport-ablation", "iso": "NYISO", "label": "nyiso 55 ldc-transport (ABLATION TWIN)", "shorthand": "nyiso-55-ldc-transport-ablation", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-07-nyiso-56-measured-zonal-ablation", "date": "2026-07-07", "definition": "G-20c KEEPER (promoted 2026-07-07, owner: 'if it's better promote it'; supersedes nyiso-53-li-tsl). Determination CALIBRATED-WITH-CAVEATS. nyiso-53 recipe VERBATIM (nyiso_li_lcr_tsl #1345 + use_plant_emission_rates_v2 + downstate CT gas basis + energy_reserve_coopt) with ONE change: the LP now dispatches on MEASURED per-zone hourly load shapes instead of the static Gold-Book shares. load_zonal_shares gained a raw-file fallback (eia_loader) so the measured NYISO 'pal' actual-load (data/raw/zone-specific-demand/NYISO, upload U3) drives every zone's own diurnal/seasonal shape even when the gitignored data/clean parquet is absent \u2014 rule-12 measured>estimate, forward-reproducible, no new free parameter. Static shares understated the downstate peak (NYC 0.28 static vs 0.34 measured at peak; LI 0.12 vs 0.17) and forced every zone to peak the same hour, so the import-constrained NYC/SENY pocket never tightened. RESULT (G-20c): with measured load the downstate pocket BINDS and the in-LP locational reserve co-opt fires \u2014 2023 NYC/Hudson LBMP spikes to $1,684 while Upstate maxes at $152 (genuinely locational). C3c tail vs RT actual: 2023 21h vs 10h (was 0h), 2025 14h vs 42h; C3a mean 2023 +1.6% vs DA (was -9.0%), C3b NRMSE 0.188/0.200/0.165 (keeper 0.182/0.221/0.190); C1/C2/C4 PASS, C7 PASS, no load-bearing regression. OPEN: 2024 (mild year) + 2025 deep >$300 tail still under \u2014 next lever is downstate import discipline (measured NYC locality import limit 2,875 MW < model Dunwoodie 3,900 MW estimate, apply in-window like #1345). C3c FAILs the DA-expressible gate (DA actual 1h) = the G-20a scoring-basis artifact, not an RT over-fire. C8 ST_GAS breach is the keeper's owner-held-legitimate G-05 item at LOWER forced share (30/45/38% vs keeper 61/70/60%) \u2014 kept+disclosed in the attestation. Governance ATTESTED; registered zero-forcing ablation twin. It dominates nyiso-53 on measured faithfulness (rule 12) + C3a/C3b with no load-bearing regression.", "file": "frontend/data/backcast/runs/2026-07-07-nyiso-56-measured-zonal.js", "id": "2026-07-07-nyiso-56-measured-zonal", "iso": "NYISO", "label": "nyiso 56 measured zonal", "market_story": "The keeper vs its zero-forcing twin isolates what the measured load shares buy on top of the merchant floors. The one change from nyiso-53 is a measured-data source swap (static Gold-Book -> measured per-zone hourly load shapes), which adds no floor and no free parameter, so the twin delta is dominated by the same PR-#1442 windowed downstate temperature ramps the nyiso-53 twin already characterised. What the measured shares change is WHERE the load sits: putting the true ~34% NYC / ~17% LI peak share into the LP (vs the flat 0.28/0.12 static) tightens the import-constrained NYC/SENY pocket, so the in-LP locational reserve co-opt fires and the downstate LBMP tail forms ($1,684/MWh in 2023, Upstate flat at $152) - real locational scarcity a NYCA-aggregate load allocation cannot produce, and it also LOWERS ST_GAS floor-forcing (30/45/38% vs 61/70/60%) because more of the downstate steam base now clears economically under the correct local load.", "shorthand": "nyiso-56-measured-zonal", "years": [2023, 2024, 2025]}, {"date": "2026-07-07", "definition": "(ABLATION TWIN of 2026-07-07-nyiso-56-measured-zonal) D-3 zero-forcing ablation twin of 2026-07-07-nyiso-56-measured-zonal (rule 21): the nyiso-56 recipe verbatim (measured per-zone load shares, G-20c) with all merchant floors/bridges zero-forced.", "file": "frontend/data/backcast/runs/2026-07-07-nyiso-56-measured-zonal-ablation.js", "id": "2026-07-07-nyiso-56-measured-zonal-ablation", "iso": "NYISO", "label": "nyiso 56 measured zonal (ABLATION TWIN)", "shorthand": "nyiso-56-measured-zonal-ablation", "years": [2023, 2024, 2025]}, {"date": "2026-07-07", "definition": "G-20c: main measured-zonal recipe + primary-source-corrected NYISO_RCPF_LOCATIONAL (SOM 2023-25 p297: East 10-min $775, SENY 1300 MW, NYC $25) in the live energy_reserve_coopt path. Single-delta A/B vs nyiso-56-measured-zonal.", "file": "frontend/data/backcast/runs/2026-07-07-nyiso-57-locational-rcpf.js", "id": "2026-07-07-nyiso-57-locational-rcpf", "iso": "NYISO", "label": "nyiso 57 locational rcpf", "shorthand": "nyiso-57-locational-rcpf", "years": [2023, 2024, 2025]}, {"date": "2026-07-07", "definition": "PJM 86 pjm-83 keeper recipe VERBATIM re-solved at HEAD: the flag-off baseline of the pjm-87 per-gen opportunity-cost A/B, on the same data tree as the treatment (regenerated clean partitions + the per-BA EIA-930 PJM demand rewire: 1-2h clock lag fixed, 2023/2024 zero-hour gaps replaced with real meter data, the 2024 interpolation-shaved ~104 GW ridge restored). No mechanism deltas vs pjm-83 \u2014 any move vs the committed pjm-83 bundle is the data tree.", "file": "frontend/data/backcast/runs/2026-07-07-pjm-86-pjm83-head.js", "id": "2026-07-07-pjm-86-pjm83-head", "iso": "PJM", "label": "pjm 86 pjm83 head", "shorthand": "pjm-86-pjm83-head", "years": [2023, 2024, 2025]}, {"date": "2026-07-07", "definition": "(PROBE \u2014 keeper decision pending the pjm-86 same-tree A/B) PJM 87 per-gen OPPORTUNITY-COST reserve co-opt (G-20b successor): pjm-83 keeper recipe VERBATIM (= the pjm-86 same-tree baseline) + pjm_reserve_pergen ((zone, fuel-class) pooled R<=ramp10 co-opt, measured RTO+MAD Primary families) + pjm_reserve_pergen_sync (NEW: measured Synchronized sub-product families sr_req_mw/mad_sr_req_mw on the published Synchronized ORDC rows; per-pool SYNC/NON-SYNC column split sharing the joint P+R row \u2014 sync servable only by ONLINE 10-min ramp, scoped at the P0->P1 seam from the P0 run pattern; offline fast-start ramp serves non-sync Primary per Manual 11 sec 4.2; energy availability NOT masked so P1 redispatch prices the opportunity cost) + measured_ramp_capability (rule 14). Fixes pjm-81's non-fire (joint headroom let idle capacity back reserve; 1 fired hour / 3 yr) by composing per-gen ramp limits WITH online scoping. RESULT: reserve dual > 0 in 133/44/50 hours (2023/24/25, mostly afternoon 11-18h) \u2014 the first PJM reserve scoping to fire nontrivially (vs pjm-81's 1h/3yr). All duals stay under $32, well below the $300 penalty step (never fires the shortage regime) \u2014 correctly sub-shortage opportunity-cost, as designed. But magnitude is modest: most positive-dual hours sit in $0-10, not the targeted $10-80 band, so this only partially engages the $75-200 afternoon residual, not a residual-closing fix.", "file": "frontend/data/backcast/runs/2026-07-07-pjm-87-pergen-oppcost.js", "id": "2026-07-07-pjm-87-pergen-oppcost", "iso": "PJM", "label": "pjm 87 pergen oppcost", "shorthand": "pjm-87-pergen-oppcost", "years": [2023, 2024, 2025]}, {"date": "2026-07-07", "definition": "(PROBE) PJM 88 size-split pergen pooling tier (pjm-87 diagnosis remedy): pjm-87 recipe VERBATIM + pjm_reserve_pergen_size_split (splits each base (zone, fuel-class) pool's plants above 2.0x the pool's own mean plant capacity into individual reserve columns -- self-normalizing threshold, no absolute MW cutoff -- 91-95 pools / 182-190 sync-split R columns vs the base 39/78; a middle ground short of the memory-infeasible full per-plant tier, 407 pools / 814 columns). Diagnosis: none of the 4 balance rows ever bind (8-14x margin at the tightest hour of 3 years); duals come from the per-pool joint headroom row, diluted by 39 uniform pools letting the LP source PJM's small requirement from any idle pool. RESULT: memory-safe (no OOM), fires ~50% more hours (205/54/70 vs pjm-87's 133/44/50) but does NOT sharpen the magnitude into the $10-80 band -- distribution shape unchanged, still >=90% in $0-10. Unlike pjm-87, introduces a real 2025-specific dispatch shift (CT_PEAKER -2.53 TWh vs pjm-87, CC_REGULAR +1.44 TWh) and a genuine #1484 CT_PEAKER D-2 drag-share movement (10.54%->11.93%, still under the 15% cap, no gate crossed). Not a promotion case -- frequency gain without magnitude gain, at a real (small) dispatch-distortion cost pjm-87 didn't have.", "file": "frontend/data/backcast/runs/2026-07-07-pjm-88-pergen-sizesplit.js", "id": "2026-07-07-pjm-88-pergen-sizesplit", "iso": "PJM", "label": "pjm 88 pergen sizesplit", "shorthand": "pjm-88-pergen-sizesplit", "years": [2023, 2024, 2025]}, {"date": "2026-07-08", "definition": "PJM 89 steam-gas overnight-drag CANDIDATE (not yet promoted keeper; pjm-83 remains keeper pending CC_CHP fix + ablation/LOO). pjm-83 recipe re-solved at HEAD absorbing four structural corrections vs pjm-83: (1) ST_GAS extreme-day OVERNIGHT [0,6] drag in the reliability_floor engine (tmax/tmin/netload day-triggers, min-must-run floor, 7 limbs enabled where the driver is real, forced-energy 3.4-6.1%); (2) CHP steam-credit power-only HR correction extended to PJM; (3) PRB 5-13d dead-stop + orphaned ST_CHP steam-boiler outage capture; (4) coal-bit econ-high held at 1.2664. VALIDATED: CT_CHP corrected 2.0->1.4-1.5 TWh (near 923); coal 146.0 vs 145.9 (EIA-930); ST_GAS drag healthy (D-1/D-2 PASS). OPEN RESIDUAL: CC_CHP still ~+50% over 923 net-to-grid - its offer multipliers (0.66x) negate the HR floor; the pending lever is merchant BTM host-share re-sizing.", "file": "frontend/data/backcast/runs/2026-07-08-pjm-89-steamgas-drag.js", "id": "2026-07-08-pjm-89-steamgas-drag", "iso": "PJM", "label": "pjm 89 steamgas drag", "shorthand": "pjm-89-steamgas-drag", "years": [2023, 2024, 2025]}];